export function solve(code: string): boolean {
  if (typeof code !== 'string') return false;

  const s = code.toUpperCase();

  // 3 owner letters, equipment category (U, J, or Z), 6 serial digits, 1 check digit
  if (!/^[A-Z]{3}[UJZ][0-9]{7}$/.test(s)) return false;

  // ISO 6346 letter values: A=10, B=12, ..., skipping multiples of 11 (11, 22, 33)
  const letterValues: Record<string, number> = {};
  let v = 10;
  for (let i = 0; i < 26; i++) {
    if (v % 11 === 0) v++;
    letterValues[String.fromCharCode(65 + i)] = v;
    v++;
  }

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const ch = s[i];
    const value = /[0-9]/.test(ch) ? ch.charCodeAt(0) - 48 : letterValues[ch];
    sum += value * Math.pow(2, i);
  }

  const expected = (sum % 11) % 10;
  const check = s.charCodeAt(10) - 48;

  return check === expected;
}

export function solve(a: string, b: string): string | null {
  const SEMVER =
    /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

  interface Parsed {
    major: string;
    minor: string;
    patch: string;
    pre: string[];
  }

  const parse = (v: string): Parsed => {
    const m = SEMVER.exec(v);
    if (!m) throw new TypeError(`Invalid semver version: ${v}`);
    return {
      major: m[1],
      minor: m[2],
      patch: m[3],
      pre: m[4] !== undefined ? m[4].split('.') : [],
    };
  };

  // Compare canonical non-negative integer strings without precision loss.
  const cmpNum = (x: string, y: string): number => {
    if (x.length !== y.length) return x.length < y.length ? -1 : 1;
    if (x === y) return 0;
    return x < y ? -1 : 1;
  };

  const cmpMain = (x: Parsed, y: Parsed): number =>
    cmpNum(x.major, y.major) || cmpNum(x.minor, y.minor) || cmpNum(x.patch, y.patch);

  const isNumeric = (s: string): boolean => /^\d+$/.test(s);

  const cmpIdent = (x: string, y: string): number => {
    const xn = isNumeric(x);
    const yn = isNumeric(y);
    if (xn && yn) return cmpNum(x, y);
    if (xn) return -1;
    if (yn) return 1;
    if (x === y) return 0;
    return x < y ? -1 : 1;
  };

  const cmpPre = (x: string[], y: string[]): number => {
    if (x.length === 0 && y.length === 0) return 0;
    if (x.length === 0) return 1;
    if (y.length === 0) return -1;
    const n = Math.min(x.length, y.length);
    for (let i = 0; i < n; i++) {
      const c = cmpIdent(x[i], y[i]);
      if (c !== 0) return c;
    }
    if (x.length === y.length) return 0;
    return x.length < y.length ? -1 : 1;
  };

  const compare = (x: Parsed, y: Parsed): number =>
    cmpMain(x, y) || cmpPre(x.pre, y.pre);

  const v1 = parse(a);
  const v2 = parse(b);
  const c = compare(v1, v2);

  if (c === 0) return null;

  const higher = c > 0 ? v1 : v2;
  const lower = c > 0 ? v2 : v1;
  const highHasPre = higher.pre.length > 0;
  const lowHasPre = lower.pre.length > 0;

  if (lowHasPre && !highHasPre) {
    // Prerelease -> release needs special handling.
    // Low version with only a major component (x.0.0-pre) always yields 'major'.
    if (lower.minor === '0' && lower.patch === '0') {
      return 'major';
    }
    // Same main version: release of the prerelease's base.
    if (cmpMain(lower, higher) === 0) {
      if (lower.minor !== '0' && lower.patch === '0') {
        return 'minor';
      }
      return 'patch';
    }
  }

  const prefix = highHasPre ? 'pre' : '';

  if (v1.major !== v2.major) return prefix + 'major';
  if (v1.minor !== v2.minor) return prefix + 'minor';
  if (v1.patch !== v2.patch) return prefix + 'patch';

  return 'prerelease';
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const s = id.replace(/[\/\\]/g, "");

  // Must be exactly 11 digits
  if (!/^[0-9]{11}$/.test(s)) return false;

  const digits = s.split("").map(Number);

  // First digit must not be zero
  if (digits[0] === 0) return false;

  // Rule on repeated digits among the first 10 digits:
  // no digit may appear more than 3 times, and exactly one digit
  // may appear 2 or 3 times (all others at most once).
  const counts = new Array<number>(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[digits[i]]++;
  }
  let repeated = 0;
  for (const c of counts) {
    if (c > 3) return false;
    if (c >= 2) repeated++;
  }
  if (repeated !== 1) return false;

  // Check digit (ISO 7064 Mod 11,10 variant)
  let prod = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (digits[i] + prod) % 10;
    if (sum === 0) sum = 10;
    prod = (sum * 2) % 11;
  }
  let check = 11 - prod;
  if (check === 10) check = 0;

  return check === digits[10];
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

interface Parsed {
  core: [string, string, string];
  pre: string[];
  build: string[];
}

function parse(v: string): Parsed {
  const m = SEMVER_RE.exec(v);
  if (!m) throw new Error(`Invalid version: ${v}`);
  return {
    core: [m[1], m[2], m[3]],
    pre: m[4] ? m[4].split(".") : [],
    build: m[5] ? m[5].split(".") : [],
  };
}

// Compare two non-negative integer strings numerically, without precision loss.
function cmpNumeric(a: string, b: string): number {
  const na = a.replace(/^0+(?=\d)/, "");
  const nb = b.replace(/^0+(?=\d)/, "");
  if (na.length !== nb.length) return na.length < nb.length ? -1 : 1;
  return na < nb ? -1 : na > nb ? 1 : 0;
}

// Mirrors node-semver's compareIdentifiers.
function cmpIdent(a: string, b: string): number {
  const an = /^[0-9]+$/.test(a);
  const bn = /^[0-9]+$/.test(b);
  if (an && bn) return cmpNumeric(a, b);
  if (an) return -1; // numeric identifiers have lower precedence
  if (bn) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

// SemVer 2.0.0 precedence (build metadata ignored).
function cmpPrecedence(x: Parsed, y: Parsed): number {
  for (let i = 0; i < 3; i++) {
    const c = cmpNumeric(x.core[i], y.core[i]);
    if (c !== 0) return c;
  }
  if (x.pre.length === 0 && y.pre.length === 0) return 0;
  if (x.pre.length === 0) return 1; // release > prerelease
  if (y.pre.length === 0) return -1;

  const len = Math.max(x.pre.length, y.pre.length);
  for (let i = 0; i < len; i++) {
    if (i >= x.pre.length) return -1; // shorter set is lower
    if (i >= y.pre.length) return 1;
    if (x.pre[i] === y.pre[i]) continue;
    const c = cmpIdent(x.pre[i], y.pre[i]);
    if (c !== 0) return c;
  }
  return 0;
}

// Mirrors node-semver's SemVer.prototype.compareBuild.
function cmpBuild(x: Parsed, y: Parsed): number {
  for (let i = 0; ; i++) {
    const a = x.build[i];
    const b = y.build[i];
    if (a === undefined && b === undefined) return 0;
    if (b === undefined) return 1;
    if (a === undefined) return -1;
    if (a === b) continue;
    return cmpIdent(a, b);
  }
}

export function solve(versions: string[]): string[] {
  const entries = versions
    .filter((v) => SEMVER_RE.test(v))
    .map((v) => ({ v, p: parse(v) }));

  entries.sort((x, y) => cmpPrecedence(x.p, y.p) || cmpBuild(x.p, y.p));

  return entries.map((e) => e.v);
}

export function solve(text: string): string | null {
  const match = text.match(
    /(^|[^\d])(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?:$|[^\d])/
  );
  if (match === null) return null;

  const parts: string[] = [match[2], match[3] || "0", match[4] || "0"];

  for (const p of parts) {
    // Leading zeros (e.g. "01") are not valid semver numeric identifiers.
    if (p.length > 1 && p.charAt(0) === "0") return null;
    // Components above MAX_SAFE_INTEGER are rejected by semver.
    if (Number(p) > Number.MAX_SAFE_INTEGER) return null;
  }

  return `${parts[0]}.${parts[1]}.${parts[2]}`;
}

export function solve(code: string): boolean {
  const s = code.toUpperCase();
  // Owner code (3 letters), equipment category (U, J, or Z), serial number and check digit (7 digits)
  if (!/^[A-Z]{3}[UJZ][0-9]{7}$/.test(s)) return false;
  return lib.isISO6346(s);
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  return lib.inc(version, kind, id);
}

export function solve(text: string): string | null {
  const version = lib.coerce(text);
  if (version === null || version === undefined) {
    return null;
  }
  return `${version.major}.${version.minor}.${version.patch}`;
}

export function solve(versions: string[]): string[] {
  // lib.sort sorts in place and returns the same array, so pass a copy
  // to avoid mutating the caller's input.
  return lib.sort([...versions]);
}

export function solve(uuid: string): string | null {
  if (typeof uuid !== "string") return null;

  // Canonical 8-4-4-4-12 hexadecimal form, either case.
  if (!/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(uuid)) {
    return null;
  }

  // 32 lowercase hex digits without hyphens.
  const h = uuid.replace(/-/g, "").toLowerCase();

  // Version must be 1 (the input is required to be a version-1 UUID).
  if (h[12] !== "1") return null;

  // RFC 9562 variant: the two most significant bits of clock_seq_hi are 10.
  if (!"89ab".includes(h[16])) return null;

  // 60-bit timestamp as 15 hex digits: time_hi (3) | time_mid (4) | time_low (8).
  const t = h.slice(13, 16) + h.slice(8, 12) + h.slice(0, 8);

  // v6 layout: time_high (32) | time_mid (16) | version 6 + time_low (12 bits)
  //            | clock_seq (16, variant included) | node (48).
  return (
    t.slice(0, 8) +
    t.slice(8, 12) +
    "6" +
    t.slice(12, 15) +
    h.slice(16, 20) +
    h.slice(20, 32)
  );
}

export function solve(a: string, b: string): string | null {
  return lib.diff(a, b);
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes before validating.
  const cleaned = id.replace(/[\/\\]/g, '');
  return lib.isTaxID(cleaned, 'de-DE');
}

export function solve(uuid: string): string | null {
  const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (typeof uuid !== 'string' || !UUID_RE.test(uuid)) {
    return null;
  }
  // RFC 9562 variant: the two most significant bits of byte 8 must be 10,
  // i.e. the first hex digit of the fourth group is one of 8, 9, a, b.
  const variantNibble = uuid[19].toLowerCase();
  if (!'89ab'.includes(variantNibble)) {
    return null;
  }
  return lib.v1ToV6(uuid.toLowerCase());
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;

  const s = code.toUpperCase();

  // 3 owner letters, 1 equipment category (U, J, or Z), 6 serial digits, 1 check digit
  if (!/^[A-Z]{3}[UJZ][0-9]{7}$/.test(s)) return false;

  // Map each character to its ISO 6346 numeric value.
  // Letters A..Z map to 10..38, skipping multiples of 11 (11, 22, 33).
  const letterValue = (ch: string): number => {
    const idx = ch.charCodeAt(0) - 65; // 'A' = 0
    let v = 10 + idx;
    if (v >= 11) v++;
    if (v >= 22) v++;
    if (v >= 33) v++;
    return v;
  };

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const ch = s[i];
    const value = /[0-9]/.test(ch) ? ch.charCodeAt(0) - 48 : letterValue(ch);
    sum += value * Math.pow(2, i);
  }

  const checkDigit = (sum % 11) % 10;
  return checkDigit === s.charCodeAt(10) - 48;
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  const MAX_SAFE = Number.MAX_SAFE_INTEGER;
  const ID = '(?:0|[1-9]\\d*|\\d*[a-zA-Z-][a-zA-Z0-9-]*)';
  const PRE = `${ID}(?:\\.${ID})*`;
  const FULL = new RegExp(
    `^v?(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-(${PRE}))?(?:\\+[0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*)?$`
  );
  const PRE_ONLY = new RegExp(`^-(${PRE})$`);

  if (typeof version !== 'string' || version.length > 256) return null;
  const m = FULL.exec(version);
  if (!m) return null;

  let major = Number(m[1]);
  let minor = Number(m[2]);
  let patch = Number(m[3]);
  if (major > MAX_SAFE || minor > MAX_SAFE || patch > MAX_SAFE) return null;

  let prerelease: (string | number)[] =
    m[4] === undefined
      ? []
      : m[4].split('.').map((x) => {
          if (/^[0-9]+$/.test(x)) {
            const n = +x;
            if (n >= 0 && n < MAX_SAFE) return n;
          }
          return x;
        });

  const isNum = (x: string | number): boolean => /^[0-9]+$/.test(String(x));

  const cmpId = (a: string | number, b: string | number): number => {
    const an = isNum(a);
    const bn = isNum(b);
    let x: any = a;
    let y: any = b;
    if (an && bn) {
      x = +a;
      y = +b;
    }
    if (x === y) return 0;
    if (an && !bn) return -1;
    if (bn && !an) return 1;
    return x < y ? -1 : 1;
  };

  const pre = (identifier?: string): void => {
    // Mirrors node-semver's 'pre' release with identifierBase undefined
    const base = 0;
    if (prerelease.length === 0) {
      prerelease = [base];
    } else {
      let i = prerelease.length;
      while (--i >= 0) {
        const v = prerelease[i];
        if (typeof v === 'number') {
          prerelease[i] = v + 1;
          i = -2;
        }
      }
      if (i === -1) {
        prerelease.push(base);
      }
    }
    if (identifier) {
      const pr: (string | number)[] = [identifier, base];
      if (cmpId(prerelease[0], identifier) === 0) {
        if (Number.isNaN(Number(prerelease[1]))) {
          prerelease = pr;
        }
      } else {
        prerelease = pr;
      }
    }
  };

  const inc = (release: string, identifier?: string): void => {
    if (release.startsWith('pre') && identifier) {
      const mm = PRE_ONLY.exec(`-${identifier}`);
      if (!mm || mm[1] !== identifier) {
        throw new Error('invalid identifier');
      }
    }

    switch (release) {
      case 'premajor':
        prerelease = [];
        patch = 0;
        minor = 0;
        major++;
        pre(identifier);
        break;
      case 'preminor':
        prerelease = [];
        patch = 0;
        minor++;
        pre(identifier);
        break;
      case 'prepatch':
        prerelease = [];
        inc('patch', identifier);
        pre(identifier);
        break;
      case 'prerelease':
        if (prerelease.length === 0) {
          inc('patch', identifier);
        }
        pre(identifier);
        break;
      case 'major':
        if (minor !== 0 || patch !== 0 || prerelease.length === 0) {
          major++;
        }
        minor = 0;
        patch = 0;
        prerelease = [];
        break;
      case 'minor':
        if (patch !== 0 || prerelease.length === 0) {
          minor++;
        }
        patch = 0;
        prerelease = [];
        break;
      case 'patch':
        if (prerelease.length === 0) {
          patch++;
        }
        prerelease = [];
        break;
      case 'pre':
        pre(identifier);
        break;
      default:
        throw new Error(`invalid increment argument: ${release}`);
    }
  };

  try {
    inc(kind, id);
  } catch {
    return null;
  }

  let out = `${major}.${minor}.${patch}`;
  if (prerelease.length) {
    out += `-${prerelease.join('.')}`;
  }
  return out;
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const s = id.replace(/[\/\\]/g, "");

  // Must be exactly 11 digits
  if (!/^\d{11}$/.test(s)) return false;

  // First digit must not be 0
  if (s[0] === "0") return false;

  // Count occurrences of each digit among the first 10 digits
  const counts: number[] = new Array(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[s.charCodeAt(i) - 48]++;
  }

  // Exactly one digit may occur 2 or 3 times; all others at most once
  let repeated = 0;
  for (const c of counts) {
    if (c === 2 || c === 3) {
      repeated++;
    } else if (c > 1) {
      return false;
    }
  }
  if (repeated !== 1) return false;

  // Check digit (ISO 7064 Mod 11,10)
  let product = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (s.charCodeAt(i) - 48 + product) % 10;
    if (sum === 0) sum = 10;
    product = (sum * 2) % 11;
  }
  let check = 11 - product;
  if (check === 10) check = 0;

  return check === s.charCodeAt(10) - 48;
}

export function solve(stamps: string[]): number[] {
  if (!Array.isArray(stamps)) {
    throw new RangeError("stamps must be an array of strings");
  }

  // lib.parseISO interprets strings without an offset in the local time zone.
  // The task requires UTC, so append "Z" to any string lacking an explicit offset.
  // Explicit offsets are handled by lib.parseISO and are not modified.
  const withExplicitUtc = (s: string): string => {
    const sep = s.search(/[T ]/);

    if (sep === -1) {
      // Date-only: no time part, so an offset is only possible as a trailing Z.
      return /Z$/.test(s) ? s : s + "Z";
    }

    // Date-time: check the time part for a trailing Z or a numeric offset.
    const timePart = s.slice(sep + 1);
    const hasOffset = /(?:Z|[+-]\d{2}(?::?\d{2})?)$/.test(timePart);
    return hasOffset ? s : s + "Z";
  };

  const epochs = stamps.map((s) => {
    if (typeof s !== "string") {
      throw new RangeError(`Invalid date: ${String(s)}`);
    }

    const parsed = lib.parseISO(withExplicitUtc(s));
    const ms = parsed.getTime();

    if (Number.isNaN(ms)) {
      throw new RangeError(`Invalid date: ${s}`);
    }
    return ms;
  });

  return epochs.sort((a, b) => a - b);
}

export function solve(text: string): string | null {
  const match = /(^|[^\d])(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?:$|[^\d])/.exec(text);
  if (match === null) return null;

  const parts = [match[2], match[3] || "0", match[4] || "0"];

  for (const part of parts) {
    // Strict semver numeric identifier: no leading zeros.
    if (!/^(0|[1-9]\d*)$/.test(part)) return null;
    // Must be a safe integer, as SemVer's constructor requires.
    if (Number(part) > Number.MAX_SAFE_INTEGER) return null;
  }

  return parts.join(".");
}

type ParsedVersion = {
  major: number;
  minor: number;
  patch: number;
  pre: string[];
};

function parseVersion(s: string): ParsedVersion {
  const m = /^\s*[v=]*\s*(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?\s*$/.exec(s);
  if (!m) {
    throw new Error(`Invalid version: ${s}`);
  }
  return {
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    pre: m[4] !== undefined ? m[4].split('.') : [],
  };
}

function cmpNum(x: number, y: number): number {
  return x === y ? 0 : x > y ? 1 : -1;
}

function cmpMain(x: ParsedVersion, y: ParsedVersion): number {
  return (
    cmpNum(x.major, y.major) ||
    cmpNum(x.minor, y.minor) ||
    cmpNum(x.patch, y.patch)
  );
}

function preEqual(x: string[], y: string[]): boolean {
  return x.length === y.length && x.every((id, i) => id === y[i]);
}

export function solve(a: string, b: string): string | null {
  const v1 = parseVersion(a);
  const v2 = parseVersion(b);

  const mc = cmpMain(v1, v2);

  // Equal ignoring build metadata
  if (mc === 0 && preEqual(v1.pre, v2.pre)) {
    return null;
  }

  // Determine which version is higher (only matters for release vs prerelease)
  const v1Higher = mc !== 0 ? mc > 0 : v1.pre.length === 0;
  const high = v1Higher ? v1 : v2;
  const low = v1Higher ? v2 : v1;

  const highHasPre = high.pre.length > 0;
  const lowHasPre = low.pre.length > 0;

  if (lowHasPre && !highHasPre) {
    // Prerelease -> release requires some kind of release
    if (!low.patch && !low.minor) {
      return 'major';
    }
    if (cmpMain(high, low) === 0) {
      if (low.minor && !low.patch) {
        return 'minor';
      }
      return 'patch';
    }
  }

  const prefix = highHasPre ? 'pre' : '';

  if (v1.major !== v2.major) {
    return prefix + 'major';
  }
  if (v1.minor !== v2.minor) {
    return prefix + 'minor';
  }
  if (v1.patch !== v2.patch) {
    return prefix + 'patch';
  }

  return 'prerelease';
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  const s = code.toUpperCase();
  // Owner code (3 letters), equipment category (U, J or Z), serial number (6 digits), check digit (1 digit)
  if (!/^[A-Z]{3}[UJZ][0-9]{7}$/.test(s)) return false;
  return lib.isISO6346(s);
}

const NUMERIC = /^[0-9]+$/;

const SEMVER =
  /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;

interface Parsed {
  core: [number, number, number];
  pre: string[];
  build: string[];
}

function parse(version: string): Parsed | null {
  const m = SEMVER.exec(version.trim());
  if (!m) return null;
  return {
    core: [Number(m[1]), Number(m[2]), Number(m[3])],
    pre: m[4] ? m[4].split(".") : [],
    build: m[5] ? m[5].split(".") : [],
  };
}

function compareIdentifiers(a: string, b: string): number {
  const an = NUMERIC.test(a);
  const bn = NUMERIC.test(b);
  if (an && bn) {
    const x = Number(a);
    const y = Number(b);
    return x === y ? 0 : x < y ? -1 : 1;
  }
  if (an) return -1;
  if (bn) return 1;
  return a === b ? 0 : a < b ? -1 : 1;
}

// Mirrors node-semver's identifier-list loop: a missing trailing
// identifier sorts lower, and the identifier comparison result is
// returned directly.
function compareLists(a: string[], b: string[]): number {
  for (let i = 0; ; i++) {
    const aMissing = i >= a.length;
    const bMissing = i >= b.length;
    if (aMissing && bMissing) return 0;
    if (bMissing) return 1;
    if (aMissing) return -1;
    if (a[i] === b[i]) continue;
    return compareIdentifiers(a[i], b[i]);
  }
}

function compareMain(a: Parsed, b: Parsed): number {
  for (let i = 0; i < 3; i++) {
    const d = a.core[i] - b.core[i];
    if (d !== 0) return d < 0 ? -1 : 1;
  }
  return 0;
}

function comparePre(a: string[], b: string[]): number {
  if (a.length === 0 && b.length === 0) return 0;
  if (a.length === 0) return 1;
  if (b.length === 0) return -1;
  return compareLists(a, b);
}

export function solve(versions: string[]): string[] {
  const items: { raw: string; p: Parsed }[] = [];
  for (const raw of versions) {
    const p = parse(raw);
    if (p !== null) items.push({ raw, p });
  }

  items.sort(
    (x, y) =>
      compareMain(x.p, y.p) ||
      comparePre(x.p.pre, y.p.pre) ||
      compareLists(x.p.build, y.p.build)
  );

  return items.map((x) => x.raw);
}

export function solve(uuid: string): string | null {
  // Canonical 8-4-4-4-12 form. Third group must start with version 1,
  // fourth group must start with an RFC 9562 variant nibble (8, 9, a, b).
  const m = /^([0-9a-f]{8})-([0-9a-f]{4})-1([0-9a-f]{3})-([89ab][0-9a-f]{3})-([0-9a-f]{12})$/i.exec(uuid);
  if (m === null) {
    return null;
  }

  const timeLow = m[1];
  const timeMid = m[2];
  const timeHi = m[3]; // 12-bit time_hi, version nibble already removed
  const clockAndNode = m[4] + m[5];

  // 60-bit timestamp as 15 hex digits: time_hi || time_mid || time_low
  const ts = timeHi + timeMid + timeLow;

  // v6 layout: time_high (bits 59..28) || time_mid (bits 27..12)
  //            || version 6 + time_low (bits 11..0) || clock_seq || node
  const hex =
    ts.slice(0, 8) +
    ts.slice(8, 12) +
    "6" +
    ts.slice(12, 15) +
    clockAndNode;

  return (
    `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-` +
    `${hex.slice(16, 20)}-${hex.slice(20, 32)}`
  ).toLowerCase();
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  return lib.inc(version, kind, id);
}

export function solve(id: string): boolean {
  const cleaned = id.replace(/[\/\\]/g, '');
  return lib.isTaxID(cleaned, 'de-DE');
}

type Id = string | number;

const MAX_SAFE = Number.MAX_SAFE_INTEGER;
const NUMERIC = /^[0-9]+$/;
const PRE_ID = '(?:0|[1-9]\\d*|\\d*[a-zA-Z-][a-zA-Z0-9-]*)';
const SEMVER_RE = new RegExp(
  '^v?(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)' +
    `(?:-(${PRE_ID}(?:\\.${PRE_ID})*))?` +
    '(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$'
);

// Mirrors node-semver's compareIdentifiers(a, b) === 0
function sameId(a: Id, b: string): boolean {
  const an = typeof a === 'number' || NUMERIC.test(a);
  const bn = NUMERIC.test(b);
  if (an && bn) return Number(a) === Number(b);
  if (an !== bn) return false;
  return a === b;
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  const m = SEMVER_RE.exec(String(version).trim());
  if (!m) return null;

  const major0 = Number(m[1]);
  const minor0 = Number(m[2]);
  const patch0 = Number(m[3]);
  if (major0 > MAX_SAFE || minor0 > MAX_SAFE || patch0 > MAX_SAFE) return null;

  let major = major0;
  let minor = minor0;
  let patch = patch0;
  let prerelease: Id[] =
    m[4] === undefined
      ? []
      : m[4].split('.').map((p): Id =>
          NUMERIC.test(p) && Number(p) < MAX_SAFE ? Number(p) : p
        );

  // Mirrors SemVer.prototype.inc('pre', id) with identifierBase undefined (base 0)
  const preInc = (): void => {
    if (prerelease.length === 0) {
      prerelease = [0];
    } else {
      let incremented = false;
      for (let i = prerelease.length - 1; i >= 0; i--) {
        const x = prerelease[i];
        if (typeof x === 'number') {
          prerelease[i] = x + 1;
          incremented = true;
          break;
        }
      }
      if (!incremented) prerelease.push(0);
    }

    if (id) {
      const next: Id[] = [id, 0];
      if (sameId(prerelease[0], id)) {
        if (isNaN(Number(prerelease[1]))) prerelease = next;
      } else {
        prerelease = next;
      }
    }
  };

  switch (kind) {
    case 'premajor':
      prerelease = [];
      patch = 0;
      minor = 0;
      major++;
      preInc();
      break;
    case 'preminor':
      prerelease = [];
      patch = 0;
      minor++;
      preInc();
      break;
    case 'prepatch':
      prerelease = [];
      patch++;
      preInc();
      break;
    case 'prerelease':
      if (prerelease.length === 0) patch++;
      preInc();
      break;
    case 'major':
      if (minor !== 0 || patch !== 0 || prerelease.length === 0) major++;
      minor = 0;
      patch = 0;
      prerelease = [];
      break;
    case 'minor':
      if (patch !== 0 || prerelease.length === 0) minor++;
      patch = 0;
      prerelease = [];
      break;
    case 'patch':
      if (prerelease.length === 0) patch++;
      prerelease = [];
      break;
    default:
      return null;
  }

  let out = `${major}.${minor}.${patch}`;
  if (prerelease.length > 0) out += '-' + prerelease.join('.');
  return out;
}

export function solve(versions: string[]): string[] {
  // lib.sort sorts in place, so pass a copy to return a new array
  return lib.sort([...versions]);
}

export function solve(text: string): string | null {
  const v = lib.coerce(text);
  if (v === null) {
    return null;
  }
  return `${v.major}.${v.minor}.${v.patch}`;
}

export function solve(a: string, b: string): string | null {
  return lib.diff(a, b);
}

export function solve(code: string): boolean {
  const s = code.toUpperCase();

  // Format: 3 owner letters, 1 equipment category letter (U, J, or Z),
  // 6 serial digits, 1 check digit.
  if (!/^[A-Z]{3}[UJZ][0-9]{7}$/.test(s)) {
    return false;
  }

  // ISO 6346 letter values (multiples of 11 are skipped: 11, 22, 33)
  const letterValues: Record<string, number> = {
    A: 10, B: 12, C: 13, D: 14, E: 15, F: 16, G: 17, H: 18, I: 19,
    J: 20, K: 21, L: 23, M: 24, N: 25, O: 26, P: 27, Q: 28, R: 29,
    S: 30, T: 31, U: 32, V: 34, W: 35, X: 36, Y: 37, Z: 38,
  };

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const ch = s[i];
    const value = /[0-9]/.test(ch) ? Number(ch) : letterValues[ch];
    sum += value * Math.pow(2, i);
  }

  const checkDigit = (sum % 11) % 10;
  return checkDigit === Number(s[10]);
}

type Form = "ext" | "basic";

const MS_PER_DAY = 86400000;
const MAX_EPOCH_MS = 8.64e15;

// Date patterns. Each supports the extended (hyphenated) or basic (compact) form.
const EXT_CALENDAR = /^([+-]\d{6}|\d{4})(?:-(\d{2})(?:-(\d{2}))?)?$/;
const BASIC_CALENDAR = /^([+-]\d{6}|\d{4})(\d{2})(\d{2})$/;
const EXT_WEEK = /^([+-]\d{6}|\d{4})-W(\d{2})(?:-(\d))?$/;
const BASIC_WEEK = /^([+-]\d{6}|\d{4})W(\d{2})(\d)?$/;
const EXT_ORDINAL = /^([+-]\d{6}|\d{4})-(\d{3})$/;
const BASIC_ORDINAL = /^([+-]\d{6}|\d{4})(\d{3})$/;

// Time patterns. Fractional seconds are allowed; reduced precision is allowed.
const EXT_TIME = /^(\d{2})(?::(\d{2})(?::(\d{2})(?:[.,](\d+))?)?)?$/;
const BASIC_TIME = /^(\d{2})(?:(\d{2})(?:(\d{2})(?:[.,](\d+))?)?)?$/;

// Offset patterns (the offset form must match the date form).
const EXT_OFFSET = /^([+-])(\d{2})(?::(\d{2}))?$/;
const BASIC_OFFSET = /^([+-])(\d{2})(\d{2})?$/;

function invalid(input: unknown): never {
  const shown = typeof input === "string" ? JSON.stringify(input) : String(input);
  throw new RangeError(`Invalid ISO 8601 date or date-time: ${shown}`);
}

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  return [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
}

function mod(a: number, n: number): number {
  return ((a % n) + n) % n;
}

// Days since 1970-01-01 for a proleptic Gregorian date (valid for any integer year).
function daysFromCivil(y: number, m: number, d: number): number {
  const yy = m <= 2 ? y - 1 : y;
  const era = Math.floor(yy / 400);
  const yoe = yy - era * 400;
  const mp = m > 2 ? m - 3 : m + 9;
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

// A week-numbering year has 53 ISO weeks if p(y) == 4 or p(y - 1) == 3.
function weeksInIsoYear(y: number): number {
  const p = (x: number): number =>
    mod(x + Math.floor(x / 4) - Math.floor(x / 100) + Math.floor(x / 400), 7);
  return p(y) === 4 || p(y - 1) === 3 ? 53 : 52;
}

// Year: 4 digits, or expanded form ±YYYYYY (-000000 is not permitted).
function parseYear(s: string): number | null {
  if (s === "-000000") return null;
  return Number(s);
}

function calendarDays(ys: string, ms?: string, ds?: string): number | null {
  const y = parseYear(ys);
  if (y === null) return null;
  const mo = ms === undefined ? 1 : Number(ms);
  const d = ds === undefined ? 1 : Number(ds);
  if (mo < 1 || mo > 12 || d < 1 || d > daysInMonth(y, mo)) return null;
  return daysFromCivil(y, mo, d);
}

function weekDays(ys: string, ws: string, ds?: string): number | null {
  const y = parseYear(ys);
  if (y === null) return null;
  const w = Number(ws);
  const dow = ds === undefined ? 1 : Number(ds); // 1 = Monday ... 7 = Sunday
  if (w < 1 || w > weeksInIsoYear(y) || dow < 1 || dow > 7) return null;
  const jan4 = daysFromCivil(y, 1, 4);
  const sinceMonday = mod(jan4 + 3, 7); // day 0 (1970-01-01) is Thursday, index 3 with Monday = 0
  const week1Monday = jan4 - sinceMonday;
  return week1Monday + (w - 1) * 7 + (dow - 1);
}

function ordinalDays(ys: string, ds: string): number | null {
  const y = parseYear(ys);
  if (y === null) return null;
  const n = Number(ds);
  if (n < 1 || n > (isLeap(y) ? 366 : 365)) return null;
  return daysFromCivil(y, 1, 1) + n - 1;
}

function withForm(days: number | null, form: Form): { days: number; form: Form } | null {
  return days === null ? null : { days, form };
}

function parseDate(s: string): { days: number; form: Form } | null {
  const extCal = EXT_CALENDAR.exec(s);
  if (extCal) return withForm(calendarDays(extCal[1], extCal[2], extCal[3]), "ext");

  const basicCal = BASIC_CALENDAR.exec(s);
  if (basicCal) return withForm(calendarDays(basicCal[1], basicCal[2], basicCal[3]), "basic");

  const extWeek = EXT_WEEK.exec(s);
  if (extWeek) return withForm(weekDays(extWeek[1], extWeek[2], extWeek[3]), "ext");

  const basicWeek = BASIC_WEEK.exec(s);
  if (basicWeek) return withForm(weekDays(basicWeek[1], basicWeek[2], basicWeek[3]), "basic");

  const extOrd = EXT_ORDINAL.exec(s);
  if (extOrd) return withForm(ordinalDays(extOrd[1], extOrd[2]), "ext");

  const basicOrd = BASIC_ORDINAL.exec(s);
  if (basicOrd) return withForm(ordinalDays(basicOrd[1], basicOrd[2]), "basic");

  return null;
}

// Returns milliseconds since midnight (24:00:00 is allowed as end of day).
function parseTime(s: string, form: Form): number | null {
  const m = (form === "ext" ? EXT_TIME : BASIC_TIME).exec(s);
  if (!m) return null;
  const h = Number(m[1]);
  const mi = m[2] === undefined ? 0 : Number(m[2]);
  const se = m[3] === undefined ? 0 : Number(m[3]);
  const frac = m[4] === undefined ? "" : m[4];

  if (h > 24 || mi > 59 || se > 59) return null;
  if (h === 24 && (mi !== 0 || se !== 0 || /[1-9]/.test(frac))) return null;

  // Truncate fractional seconds to whole milliseconds.
  const ms = Number((frac + "00").slice(0, 3));
  return h * 3600000 + mi * 60000 + se * 1000 + ms;
}

// Returns the offset from UTC in minutes.
function parseOffset(s: string, form: Form): number | null {
  if (s === "Z" || s === "z") return 0;
  const m = (form === "ext" ? EXT_OFFSET : BASIC_OFFSET).exec(s);
  if (!m) return null;
  const hh = Number(m[2]);
  const mm = m[3] === undefined ? 0 : Number(m[3]);
  if (hh > 23 || mm > 59) return null;
  const total = hh * 60 + mm;
  return m[1] === "-" ? -total : total;
}

function parseStamp(input: string): number {
  if (typeof input !== "string") return invalid(input);

  const tIdx = input.search(/[Tt]/);
  const date = parseDate(tIdx < 0 ? input : input.slice(0, tIdx));
  if (!date) return invalid(input);

  let msOfDay = 0;
  let offsetMin = 0;

  if (tIdx >= 0) {
    const rest = input.slice(tIdx + 1);
    // Split the time from the offset at the first Z/z/+/- character.
    const split = /^([^Zz+-]*)([\s\S]*)$/.exec(rest) as RegExpExecArray;
    const timeStr = split[1];
    const offStr = split[2];

    const t = parseTime(timeStr, date.form);
    if (t === null) return invalid(input);
    msOfDay = t;

    if (offStr !== "") {
      const off = parseOffset(offStr, date.form);
      if (off === null) return invalid(input);
      offsetMin = off;
    }
  }

  // Strings without an offset are UTC.
  const epoch = date.days * MS_PER_DAY + msOfDay - offsetMin * 60000;
  if (!(Math.abs(epoch) <= MAX_EPOCH_MS)) {
    throw new RangeError(`ISO 8601 value out of JavaScript Date range: ${input}`);
  }
  return epoch;
}

export function solve(stamps: string[]): number[] {
  if (!Array.isArray(stamps)) {
    throw new RangeError("Expected an array of ISO 8601 strings");
  }
  const result = stamps.map((s) => parseStamp(s));
  result.sort((a, b) => a - b);
  return result;
}

export function solve(uuid: string): string | null {
    if (typeof uuid !== 'string') return null;

    const s = uuid.toLowerCase();

    // Canonical 8-4-4-4-12 hexadecimal form.
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(s)) {
        return null;
    }

    // RFC 9562 variant: the two most significant bits of byte 8 are 10,
    // so the first hex digit of the fourth group is 8, 9, a or b.
    const variantNibble = s.charAt(19);
    if (!'89ab'.includes(variantNibble)) return null;

    try {
        const result = lib.v1ToV6(s);
        return typeof result === 'string' ? result.toLowerCase() : null;
    } catch {
        return null;
    }
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const s = id.replace(/[\/\\]/g, "");

  // Must be exactly 11 ASCII digits, first digit not zero
  if (!/^[0-9]{11}$/.test(s)) return false;
  if (s[0] === "0") return false;

  const digits = s.split("").map((c) => c.charCodeAt(0) - 48);

  // Repeated-digit rule on the first 10 digits:
  // exactly one digit occurs 2 or 3 times, all other digits occur at most once
  const counts: number[] = new Array(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[digits[i]]++;
  }
  let repeated = 0;
  for (let d = 0; d < 10; d++) {
    const c = counts[d];
    if (c === 2 || c === 3) {
      repeated++;
    } else if (c > 1) {
      // occurs 4+ times, or more than one digit repeated in a disallowed way
      return false;
    }
  }
  if (repeated !== 1) return false;

  // Check digit (ISO 7064 Mod 11,10 style computation)
  let product = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (digits[i] + product) % 10;
    if (sum === 0) sum = 10;
    product = (sum * 2) % 11;
  }
  let check = 11 - product;
  if (check === 10) check = 0;

  return check === digits[10];
}

export function solve(text: string): string | null {
  // Same pattern as node-semver 7's COERCE regex (MAX_SAFE_COMPONENT_LENGTH = 16).
  const COERCE = /(^|[^\d])(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?:$|[^\d])/;

  const match = COERCE.exec(text);
  if (match === null) return null;

  const parts = [match[2], match[3] ?? "0", match[4] ?? "0"];

  // Mirror SemVer parsing: no leading zeros, and each component must be <= MAX_SAFE_INTEGER.
  for (const p of parts) {
    if (!/^(0|[1-9]\d*)$/.test(p)) return null;
    if (Number(p) > Number.MAX_SAFE_INTEGER) return null;
  }

  return parts.join(".");
}

type Parsed = { main: [string, string, string]; pre: string[] };

const SEMVER_RE =
  /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

function parse(v: string): Parsed {
  const m = SEMVER_RE.exec(v.trim());
  if (!m) {
    throw new TypeError(`Invalid version: ${v}`);
  }
  return {
    main: [m[1], m[2], m[3]],
    pre: m[4] ? m[4].split('.') : [],
  };
}

// Compare canonical (no leading zeros) numeric strings.
function compareNumStr(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

function compareIdent(a: string, b: string): number {
  const aNum = /^\d+$/.test(a);
  const bNum = /^\d+$/.test(b);
  if (aNum && bNum) return compareNumStr(a, b);
  if (aNum) return -1;
  if (bNum) return 1;
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

function comparePre(a: string[], b: string[]): number {
  if (a.length === 0 && b.length === 0) return 0;
  if (a.length === 0) return 1; // release > prerelease
  if (b.length === 0) return -1;
  const len = Math.min(a.length, b.length);
  for (let i = 0; i < len; i++) {
    const c = compareIdent(a[i], b[i]);
    if (c !== 0) return c;
  }
  if (a.length === b.length) return 0;
  return a.length < b.length ? -1 : 1;
}

function compareMain(a: Parsed, b: Parsed): number {
  for (let i = 0; i < 3; i++) {
    const c = compareNumStr(a.main[i], b.main[i]);
    if (c !== 0) return c;
  }
  return 0;
}

function compare(a: Parsed, b: Parsed): number {
  const m = compareMain(a, b);
  if (m !== 0) return m;
  return comparePre(a.pre, b.pre);
}

export function solve(a: string, b: string): string | null {
  const v1 = parse(a);
  const v2 = parse(b);
  const cmp = compare(v1, v2);
  if (cmp === 0) return null;

  const high = cmp > 0 ? v1 : v2;
  const low = cmp > 0 ? v2 : v1;
  const highHasPre = high.pre.length > 0;
  const lowHasPre = low.pre.length > 0;

  const isZero = (s: string) => s === '0';

  if (lowHasPre && !highHasPre) {
    // Prerelease -> release requires special handling.
    // If the low version has only a major component (minor and patch are 0),
    // the change is always a major.
    if (isZero(low.main[1]) && isZero(low.main[2])) {
      return 'major';
    }
    // If the main version is unchanged:
    if (compareMain(low, high) === 0) {
      if (!isZero(low.main[1]) && isZero(low.main[2])) {
        return 'minor';
      }
      return 'patch';
    }
  }

  const prefix = highHasPre ? 'pre' : '';

  if (v1.main[0] !== v2.main[0]) return prefix + 'major';
  if (v1.main[1] !== v2.main[1]) return prefix + 'minor';
  if (v1.main[2] !== v2.main[2]) return prefix + 'patch';

  return 'prerelease';
}

export function solve(stamps: string[]): number[] {
  if (!Array.isArray(stamps)) {
    throw new RangeError("stamps must be an array of strings");
  }

  const epochs = stamps.map((stamp) => {
    if (typeof stamp !== "string") {
      throw new RangeError(`Not a valid date: ${String(stamp)}`);
    }

    // lib.parseISO interprets offset-less strings in the local time zone,
    // so append an explicit UTC designator before delegating to it.
    const date = lib.parseISO(withExplicitOffset(stamp));
    const ms = date.getTime();

    if (Number.isNaN(ms)) {
      throw new RangeError(`Not a valid date: "${stamp}"`);
    }
    return ms;
  });

  return epochs.sort((a, b) => a - b);
}

/**
 * Returns true if the ISO string already carries an offset designator
 * (Z, +hh[:mm], or -hh[:mm]) in its time part, or a trailing Z on a date-only string.
 */
function hasOffset(s: string): boolean {
  const sep = s.search(/[T ]/);
  if (sep === -1) {
    // Date-only: the only offset designator that can appear is a trailing Z.
    return s.endsWith("Z");
  }
  // Time part: '-' and '+' cannot occur in a plain time, so any of these means an offset.
  return /[Z+-]/.test(s.slice(sep + 1));
}

function withExplicitOffset(s: string): string {
  return hasOffset(s) ? s : s + "Z";
}

interface ParsedVersion {
  raw: string;
  core: string[];
  pre: string[] | null;
  build: string[];
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

const NUMERIC_RE = /^[0-9]+$/;

// Compare two non-negative integer strings exactly (no precision loss).
function cmpNumStr(a: string, b: string): number {
  const x = a.replace(/^0+(?=\d)/, "");
  const y = b.replace(/^0+(?=\d)/, "");
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

// Mirrors node-semver's compareIdentifiers.
function cmpIdent(a: string, b: string): number {
  const anum = NUMERIC_RE.test(a);
  const bnum = NUMERIC_RE.test(b);
  if (anum && bnum) return cmpNumStr(a, b);
  if (a === b) return 0;
  if (anum && !bnum) return -1;
  if (bnum && !anum) return 1;
  return a < b ? -1 : 1;
}

// Prerelease precedence per SemVer 2.0.0; no prerelease > any prerelease.
function cmpPre(a: string[] | null, b: string[] | null): number {
  if (a === null && b === null) return 0;
  if (a === null) return 1;
  if (b === null) return -1;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const r = cmpIdent(a[i], b[i]);
    if (r !== 0) return r;
  }
  if (a.length === b.length) return 0;
  return a.length < b.length ? -1 : 1;
}

// Mirrors node-semver's SemVer.prototype.compareBuild.
function cmpBuild(a: string[], b: string[]): number {
  for (let i = 0; ; i++) {
    const x = a[i];
    const y = b[i];
    if (x === undefined && y === undefined) return 0;
    if (y === undefined) return 1;
    if (x === undefined) return -1;
    if (x === y) continue;
    return cmpIdent(x, y);
  }
}

function compareVersions(a: ParsedVersion, b: ParsedVersion): number {
  for (let i = 0; i < 3; i++) {
    const r = cmpNumStr(a.core[i], b.core[i]);
    if (r !== 0) return r;
  }
  const p = cmpPre(a.pre, b.pre);
  if (p !== 0) return p;
  return cmpBuild(a.build, b.build);
}

export function solve(versions: string[]): string[] {
  const parsed: ParsedVersion[] = [];
  for (const raw of versions) {
    const m = SEMVER_RE.exec(raw);
    if (!m) continue;
    parsed.push({
      raw,
      core: [m[1], m[2], m[3]],
      pre: m[4] !== undefined ? m[4].split(".") : null,
      build: m[5] !== undefined ? m[5].split(".") : [],
    });
  }
  parsed.sort(compareVersions);
  return parsed.map((p) => p.raw);
}

export function solve(code: string): boolean {
  const s = code.toUpperCase();
  // Owner code (3 letters), equipment category U/J/Z, serial (6 digits), check digit (1 digit)
  if (!/^[A-Z]{3}[UJZ][0-9]{7}$/.test(s)) return false;
  return lib.isISO6346(s);
}

export function solve(uuid: string): string | null {
  // Canonical 8-4-4-4-12 form, version nibble 1, RFC 9562 variant (10xx: 8, 9, a, b).
  const m = /^([0-9a-f]{8})-([0-9a-f]{4})-1([0-9a-f]{3})-([89ab][0-9a-f]{3})-([0-9a-f]{12})$/i.exec(uuid);
  if (m === null) return null;

  const timeLow = m[1];
  const timeMid = m[2];
  const timeHi = m[3];   // 12-bit time_hi (version nibble already stripped)
  const clockSeq = m[4]; // variant bits + clock_seq, carried over unchanged
  const node = m[5];

  // 60-bit timestamp as 15 hex digits: time_hi | time_mid | time_low
  const ts = timeHi + timeMid + timeLow;

  // RFC 9562 v6 layout: time_high (32) - time_mid (16) - ver(4) + time_low (12) - variant + clock_seq - node
  const v6 =
    ts.slice(0, 8) + "-" +
    ts.slice(8, 12) + "-" +
    "6" + ts.slice(12, 15) + "-" +
    clockSeq + "-" +
    node;

  return v6.toLowerCase();
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  const MAX = Number.MAX_SAFE_INTEGER;
  const ID = '(?:0|[1-9]\\d*|\\d*[a-zA-Z-][a-zA-Z0-9-]*)';
  const FULL = new RegExp(
    '^v?(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)' +
    `(?:-(${ID}(?:\\.${ID})*))?` +
    '(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$'
  );

  const m = FULL.exec(version.trim());
  if (!m) return null;

  const nums = [Number(m[1]), Number(m[2]), Number(m[3])];
  if (nums.some((n) => n > MAX)) return null;

  let major = nums[0];
  let minor = nums[1];
  let patch = nums[2];

  let pre: Array<string | number> = m[4]
    ? m[4].split('.').map((p) => {
        if (/^[0-9]+$/.test(p)) {
          const n = +p;
          if (n >= 0 && n < MAX) return n;
        }
        return p;
      })
    : [];

  // Mirrors node-semver's compareIdentifiers; returns 0 when equal.
  const cmpIds = (a: string | number, b: string | number): number => {
    const an = /^[0-9]+$/.test(String(a));
    const bn = /^[0-9]+$/.test(String(b));
    let x: string | number = a;
    let y: string | number = b;
    if (an && bn) {
      x = Number(a);
      y = Number(b);
    }
    if (x === y) return 0;
    if (an && !bn) return -1;
    if (bn && !an) return 1;
    return x < y ? -1 : 1;
  };

  const preInc = () => {
    const base = 0; // identifierBase is never set in this call form
    if (pre.length === 0) {
      pre = [base];
    } else {
      let incremented = false;
      for (let i = pre.length - 1; i >= 0; i--) {
        const v = pre[i];
        if (typeof v === 'number') {
          pre[i] = v + 1;
          incremented = true;
          break;
        }
      }
      if (!incremented) pre.push(base);
    }

    if (id) {
      const next: Array<string | number> = [id, base];
      if (cmpIds(pre[0], id) === 0) {
        if (Number.isNaN(Number(pre[1]))) pre = next;
      } else {
        pre = next;
      }
    }
  };

  switch (kind) {
    case 'premajor':
      pre = [];
      patch = 0;
      minor = 0;
      major++;
      preInc();
      break;
    case 'preminor':
      pre = [];
      patch = 0;
      minor++;
      preInc();
      break;
    case 'prepatch':
      pre = [];
      patch++;
      preInc();
      break;
    case 'prerelease':
      if (pre.length === 0) patch++;
      preInc();
      break;
    case 'major':
      if (minor !== 0 || patch !== 0 || pre.length === 0) major++;
      minor = 0;
      patch = 0;
      pre = [];
      break;
    case 'minor':
      if (patch !== 0 || pre.length === 0) minor++;
      patch = 0;
      pre = [];
      break;
    case 'patch':
      if (pre.length === 0) patch++;
      pre = [];
      break;
    default:
      return null;
  }

  let out = `${major}.${minor}.${patch}`;
  if (pre.length) out += '-' + pre.join('.');
  return out;
}

export function solve(version: string, kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease', id?: string): string | null {
  return lib.inc(version, kind, id) ?? null;
}

export function solve(text: string): string | null {
  const v = lib.coerce(text);
  if (v === null) {
    return null;
  }
  return `${v.major}.${v.minor}.${v.patch}`;
}

export function solve(versions: string[]): string[] {
  // lib.sort sorts in place and returns the same array, so pass a copy
  // to leave the input untouched and return a new array.
  return lib.sort([...versions]);
}

export function solve(a: string, b: string): string | null {
  return lib.diff(a, b);
}

export function solve(code: string): boolean {
  if (typeof code !== 'string') return false;

  const s = code.toUpperCase();

  // Format: 3 owner letters, 1 equipment category (U, J, or Z), 6 serial digits, 1 check digit
  if (!/^[A-Z]{3}[UJZ][0-9]{7}$/.test(s)) return false;

  // ISO 6346 letter values: A=10, B=12, ... skipping multiples of 11 (11, 22, 33)
  const letterValues = new Map<string, number>();
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let value = 10;
  for (const ch of alphabet) {
    if (value % 11 === 0) value++;
    letterValues.set(ch, value);
    value++;
  }

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const ch = s[i];
    const v = i < 4 ? (letterValues.get(ch) as number) : Number(ch);
    sum += v * Math.pow(2, i);
  }

  const checkDigit = (sum % 11) % 10;
  return checkDigit === Number(s[10]);
}

export function solve(uuid: string): string | null {
    const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (typeof uuid !== 'string' || !UUID_RE.test(uuid)) {
        return null;
    }

    // Version nibble is the first character of the third group (index 14).
    if (uuid[14] !== '1') {
        return null;
    }

    // RFC 9562 variant: the first nibble of the fourth group (index 19) must be 8, 9, a, or b.
    const variantNibble = uuid[19].toLowerCase();
    if (!'89ab'.includes(variantNibble)) {
        return null;
    }

    return (lib.v1ToV6(uuid) as string).toLowerCase();
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes before validating.
  const cleaned = id.replace(/[\/\\]/g, '');

  // Digits-only, 11 characters. The library also checks this and the leading digit.
  if (!/^\d{11}$/.test(cleaned)) return false;

  // Library call for the format (leading digit not 0) and the check digit.
  if (!lib.isTaxID(cleaned, 'de-DE')) return false;

  // Repeated-digit rule over the first 10 digits:
  // exactly one digit occurs 2 or 3 times, and every other digit occurs at most once.
  const counts: number[] = [];
  for (let d = 0; d < 10; d++) counts.push(0);
  for (let i = 0; i < 10; i++) {
    counts[cleaned.charCodeAt(i) - 48]++;
  }

  let repeated = 0;
  for (const c of counts) {
    if (c > 1) {
      if (c > 3) return false;
      repeated++;
    }
  }
  return repeated === 1;
}

function withUtcDefault(s: string): string {
  // Split into date and time parts on the first 'T' or space, mirroring the library's delimiter.
  const m = /^([^T ]*)(?:[T ]([\s\S]*))?$/.exec(s);
  if (m === null) return s; // Let the library reject it.

  const datePart = m[1];
  const timePart = m[2];
  if (datePart === "") return s;

  // Date-only: give it a midnight UTC time so the library's local-time branch is never used.
  if (timePart === undefined) return `${datePart}T00:00Z`;

  // Time with an explicit offset ('Z', '+hh:mm', '-hhmm', ...): leave it alone.
  if (/[Zz+-]/.test(timePart)) return s;

  // Date-time without an offset: the time is UTC by specification.
  return `${datePart}T${timePart}Z`;
}

export function solve(stamps: string[]): number[] {
  const epochs = stamps.map((s) => {
    if (typeof s !== "string") {
      throw new RangeError(`Not a valid ISO 8601 date: ${String(s)}`);
    }
    const date = lib.parseISO(withUtcDefault(s));
    const ms = date.getTime();
    if (Number.isNaN(ms)) {
      throw new RangeError(`Not a valid ISO 8601 date: ${s}`);
    }
    return ms;
  });

  return epochs.sort((a, b) => a - b);
}

export function solve(id: string): boolean {
  const s = id.replace(/[\/\\]/g, "");
  if (!/^\d{11}$/.test(s)) return false;

  const d = s.split("").map(Number);

  // The first digit must not be zero.
  if (d[0] === 0) return false;

  // Among the first 10 digits, exactly one digit occurs 2 or 3 times,
  // and every other digit occurs at most once.
  const counts = new Array<number>(10).fill(0);
  for (let i = 0; i < 10; i++) counts[d[i]]++;
  let repeated = 0;
  for (const c of counts) {
    if (c > 3) return false;
    if (c === 2 || c === 3) repeated++;
  }
  if (repeated !== 1) return false;

  // Check digit (ISO 7064 Mod 11,10 variant).
  let prod = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (d[i] + prod) % 10;
    if (sum === 0) sum = 10;
    prod = (sum * 2) % 11;
  }
  let check = 11 - prod;
  if (check === 10) check = 0;

  return check === d[10];
}

type Parsed = {
  major: string;
  minor: string;
  patch: string;
  pre: string[];
};

const SEMVER_RE =
  /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;

function parse(v: string): Parsed {
  const m = SEMVER_RE.exec(v.trim());
  if (!m) {
    throw new TypeError(`Invalid semver version: ${v}`);
  }
  return {
    major: m[1],
    minor: m[2],
    patch: m[3],
    pre: m[4] ? m[4].split(".") : [],
  };
}

// Compare two canonical numeric strings (no leading zeros) without precision loss.
function cmpNum(x: string, y: string): number {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function cmpIdent(x: string, y: string): number {
  const xn = /^\d+$/.test(x);
  const yn = /^\d+$/.test(y);
  if (xn && yn) return cmpNum(x, y);
  if (xn) return -1; // numeric identifiers sort lower than alphanumeric
  if (yn) return 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function comparePre(a: string[], b: string[]): number {
  // A version without prerelease has higher precedence than one with it.
  if (a.length === 0 && b.length === 0) return 0;
  if (a.length === 0) return 1;
  if (b.length === 0) return -1;

  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const c = cmpIdent(a[i], b[i]);
    if (c !== 0) return c;
  }
  if (a.length === b.length) return 0;
  return a.length < b.length ? -1 : 1;
}

function compare(a: Parsed, b: Parsed): number {
  const main =
    cmpNum(a.major, b.major) ||
    cmpNum(a.minor, b.minor) ||
    cmpNum(a.patch, b.patch);
  if (main !== 0) return main;
  return comparePre(a.pre, b.pre);
}

export function solve(a: string, b: string): string | null {
  const v1 = parse(a);
  const v2 = parse(b);
  const cmp = compare(v1, v2);

  if (cmp === 0) {
    return null;
  }

  const v1Higher = cmp > 0;
  const high = v1Higher ? v1 : v2;
  const low = v1Higher ? v2 : v1;
  const highHasPre = high.pre.length > 0;
  const lowHasPre = low.pre.length > 0;

  if (lowHasPre && !highHasPre) {
    // Going from prerelease to a release requires a release type.
    if (low.patch === "0" && low.minor === "0") {
      return "major";
    }
    if (high.patch !== "0") {
      return "patch";
    }
    if (high.minor !== "0") {
      return "minor";
    }
    return "major";
  }

  const prefix = highHasPre ? "pre" : "";

  if (v1.major !== v2.major) {
    return prefix + "major";
  }
  if (v1.minor !== v2.minor) {
    return prefix + "minor";
  }
  if (v1.patch !== v2.patch) {
    return prefix + "patch";
  }

  // Both versions share the same major.minor.patch and differ only in prerelease.
  return "prerelease";
}

export function solve(text: string): string | null {
  const match = text.match(
    /(^|[^\d])(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?:$|[^\d])/
  );
  if (match === null) {
    return null;
  }

  const major = Number(match[2]);
  const minor = match[3] !== undefined ? Number(match[3]) : 0;
  const patch = match[4] !== undefined ? Number(match[4]) : 0;

  // node-semver's SemVer constructor throws when a component exceeds MAX_SAFE_INTEGER
  const MAX_SAFE = Number.MAX_SAFE_INTEGER;
  if (major > MAX_SAFE || minor > MAX_SAFE || patch > MAX_SAFE) {
    throw new TypeError("Invalid version component: exceeds MAX_SAFE_INTEGER");
  }

  return `${major}.${minor}.${patch}`;
}

type Parsed = {
  core: string[];
  pre: string[];
  build: string[];
};

function parseVersion(raw: string): Parsed {
  let s = raw.trim();
  if (s.startsWith("v") || s.startsWith("V")) s = s.slice(1);

  let build: string[] = [];
  const plus = s.indexOf("+");
  if (plus >= 0) {
    build = s.slice(plus + 1).split(".");
    s = s.slice(0, plus);
  }

  let pre: string[] = [];
  let core: string[];
  const dash = s.indexOf("-");
  if (dash >= 0) {
    pre = s.slice(dash + 1).split(".");
    core = s.slice(0, dash).split(".");
  } else {
    core = s.split(".");
  }

  return { core, pre, build };
}

function isNumeric(s: string): boolean {
  return /^[0-9]+$/.test(s);
}

// Compare two non-negative integer strings without precision loss.
function compareNumeric(a: string, b: string): number {
  const x = a.replace(/^0+(?=\d)/, "");
  const y = b.replace(/^0+(?=\d)/, "");
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

// Compare a single pre-release or build identifier per SemVer rules.
function compareIdentifier(a: string, b: string): number {
  const an = isNumeric(a);
  const bn = isNumeric(b);
  if (an && bn) return compareNumeric(a, b);
  if (an) return -1;
  if (bn) return 1;
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

// Compare identifier lists; a shorter list that is a prefix of a longer one is smaller.
function compareIdentifierLists(a: string[], b: string[]): number {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const r = compareIdentifier(a[i], b[i]);
    if (r !== 0) return r;
  }
  if (a.length === b.length) return 0;
  return a.length < b.length ? -1 : 1;
}

function compareMain(a: Parsed, b: Parsed): number {
  for (let i = 0; i < 3; i++) {
    const r = compareNumeric(a.core[i] ?? "0", b.core[i] ?? "0");
    if (r !== 0) return r;
  }
  return 0;
}

function comparePre(a: Parsed, b: Parsed): number {
  const aHas = a.pre.length > 0;
  const bHas = b.pre.length > 0;
  if (!aHas && !bHas) return 0;
  if (!aHas) return 1; // release is greater than any pre-release
  if (!bHas) return -1;
  return compareIdentifierLists(a.pre, b.pre);
}

function compareBuild(a: Parsed, b: Parsed): number {
  return compareIdentifierLists(a.build, b.build);
}

function compareVersions(a: Parsed, b: Parsed): number {
  return compareMain(a, b) || comparePre(a, b) || compareBuild(a, b);
}

export function solve(versions: string[]): string[] {
  return versions
    .map((raw) => ({ raw, parsed: parseVersion(raw) }))
    .sort((x, y) => compareVersions(x.parsed, y.parsed))
    .map((entry) => entry.raw);
}

export function solve(uuid: string): string | null {
  // Canonical 8-4-4-4-12 form, version nibble must be 1 (v1 input),
  // variant must be RFC 9562's (10xx, i.e. one of 8, 9, a, b).
  const m = /^([0-9a-f]{8})-([0-9a-f]{4})-1([0-9a-f]{3})-([89ab][0-9a-f]{3})-([0-9a-f]{12})$/i.exec(uuid);
  if (m === null) {
    return null;
  }

  const timeLow = m[1];
  const timeMid = m[2];
  const timeHi = m[3]; // 12-bit time_hi, version nibble already removed
  const clockSeq = m[4];
  const node = m[5];

  // 60-bit timestamp as 15 hex digits: time_hi | time_mid | time_low
  const timestamp = timeHi + timeMid + timeLow;

  // v6 layout: time_high (32 bits) - time_mid (16 bits) - version 6 + time_low (12 bits)
  const timeHigh = timestamp.slice(0, 8);
  const newTimeMid = timestamp.slice(8, 12);
  const timeLowAndVersion = "6" + timestamp.slice(12, 15);

  return `${timeHigh}-${newTimeMid}-${timeLowAndVersion}-${clockSeq}-${node}`.toLowerCase();
}

export function solve(code: string): boolean {
  const s = code.toUpperCase();
  if (s.length !== 11) return false;
  // Owner code (3 letters), equipment category (U, J or Z), serial number (6 digits), check digit (1 digit)
  if (!/^[A-Z]{3}[UJZ][0-9]{7}$/.test(s)) return false;
  return lib.isISO6346(s);
}

const DAY_MS = 86400000;
const MAX_MS = 8.64e15;

type Style = "ext" | "basic" | "any";

interface ParsedDate {
  year: number;
  month: number;
  day: number;
  style: Style;
  complete: boolean;
}

interface ParsedTime {
  hour: number;
  minute: number;
  second: number;
  millis: number;
  offsetMs: number;
}

const YEAR = String.raw`(\d{4}|[+-]\d{6})`;

const RE_YEAR = new RegExp(String.raw`^${YEAR}$`);
const RE_YEAR_MONTH = new RegExp(String.raw`^${YEAR}-(\d{2})$`);
const RE_CAL_EXT = new RegExp(String.raw`^${YEAR}-(\d{2})-(\d{2})$`);
const RE_CAL_BASIC = new RegExp(String.raw`^${YEAR}(\d{2})(\d{2})$`);
const RE_WEEK_EXT = new RegExp(String.raw`^${YEAR}-W(\d{2})(?:-(\d))?$`);
const RE_WEEK_BASIC = new RegExp(String.raw`^${YEAR}W(\d{2})(\d)?$`);
const RE_ORD_EXT = new RegExp(String.raw`^${YEAR}-(\d{3})$`);
const RE_ORD_BASIC = new RegExp(String.raw`^${YEAR}(\d{3})$`);

const RE_TIME_EXT =
  /^(\d{2})(?::(\d{2})(?::(\d{2})(?:[.,](\d+))?)?)?(Z|[+-]\d{2}(?::\d{2})?)?$/;
const RE_TIME_BASIC =
  /^(\d{2})(?:(\d{2})(?:(\d{2})(?:[.,](\d+))?)?)?(Z|[+-]\d{2}(?:\d{2})?)?$/;

function mod(n: number, m: number): number {
  return ((n % m) + m) % m;
}

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  if (m === 2) return isLeap(y) ? 29 : 28;
  return m === 4 || m === 6 || m === 9 || m === 11 ? 30 : 31;
}

// Days since 1970-01-01 for a proleptic Gregorian date (no Date object, so
// years 0..99 are handled correctly).
function daysFromCivil(y: number, m: number, d: number): number {
  const yy = m <= 2 ? y - 1 : y;
  const era = Math.floor(yy / 400);
  const yoe = yy - era * 400;
  const mp = (m + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function civilFromDays(z: number): { year: number; month: number; day: number } {
  z += 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor(
    (doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365
  );
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const day = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const month = mp < 10 ? mp + 3 : mp - 9;
  return { year: month <= 2 ? y + 1 : y, month, day };
}

// ISO weekday: Monday = 1 ... Sunday = 7. Day 0 (1970-01-01) is a Thursday.
function isoWeekday(days: number): number {
  return mod(days + 3, 7) + 1;
}

function weeksInYear(y: number): number {
  const jan1 = daysFromCivil(y, 1, 1);
  const dec28 = daysFromCivil(y, 12, 28); // always in the last ISO week of its year
  const ordinal = dec28 - jan1 + 1;
  return Math.floor((ordinal - isoWeekday(dec28) + 10) / 7);
}

function parseYear(t: string): number | null {
  if (t[0] === "+" || t[0] === "-") {
    const n = parseInt(t.slice(1), 10);
    if (t[0] === "-" && n === 0) return null; // -000000 is not allowed
    return t[0] === "-" ? -n : n;
  }
  return parseInt(t, 10);
}

function makeCalendar(
  ys: string,
  ms: string | undefined,
  ds: string | undefined,
  style: Style
): ParsedDate | null {
  const year = parseYear(ys);
  if (year === null) return null;
  const month = ms === undefined ? 1 : parseInt(ms, 10);
  const day = ds === undefined ? 1 : parseInt(ds, 10);
  if (month < 1 || month > 12) return null;
  if (day < 1 || day > daysInMonth(year, month)) return null;
  return { year, month, day, style, complete: ds !== undefined };
}

function makeWeek(
  ys: string,
  ws: string,
  ds: string | undefined,
  style: Style
): ParsedDate | null {
  const year = parseYear(ys);
  if (year === null) return null;
  const week = parseInt(ws, 10);
  if (week < 1 || week > weeksInYear(year)) return null;
  const dow = ds === undefined ? 1 : parseInt(ds, 10);
  if (dow < 1 || dow > 7) return null;
  const jan4 = daysFromCivil(year, 1, 4);
  const monday = jan4 - (isoWeekday(jan4) - 1);
  const c = civilFromDays(monday + (week - 1) * 7 + (dow - 1));
  return { year: c.year, month: c.month, day: c.day, style, complete: ds !== undefined };
}

function makeOrdinal(ys: string, ns: string, style: Style): ParsedDate | null {
  const year = parseYear(ys);
  if (year === null) return null;
  const n = parseInt(ns, 10);
  if (n < 1 || n > (isLeap(year) ? 366 : 365)) return null;
  const c = civilFromDays(daysFromCivil(year, 1, 1) + n - 1);
  return { year: c.year, month: c.month, day: c.day, style, complete: true };
}

function parseDate(s: string): ParsedDate | null {
  let m: RegExpExecArray | null;
  if ((m = RE_CAL_EXT.exec(s))) return makeCalendar(m[1], m[2], m[3], "ext");
  if ((m = RE_CAL_BASIC.exec(s))) return makeCalendar(m[1], m[2], m[3], "basic");
  if ((m = RE_YEAR_MONTH.exec(s))) return makeCalendar(m[1], m[2], undefined, "ext");
  if ((m = RE_YEAR.exec(s))) return makeCalendar(m[1], undefined, undefined, "any");
  if ((m = RE_WEEK_EXT.exec(s))) return makeWeek(m[1], m[2], m[3], "ext");
  if ((m = RE_WEEK_BASIC.exec(s))) return makeWeek(m[1], m[2], m[3], "basic");
  if ((m = RE_ORD_EXT.exec(s))) return makeOrdinal(m[1], m[2], "ext");
  if ((m = RE_ORD_BASIC.exec(s))) return makeOrdinal(m[1], m[2], "basic");
  return null;
}

function parseTime(t: string, style: Style): ParsedTime | null {
  const m = (style === "basic" ? RE_TIME_BASIC : RE_TIME_EXT).exec(t);
  if (!m) return null;

  const hour = parseInt(m[1], 10);
  const minute = m[2] === undefined ? 0 : parseInt(m[2], 10);
  const second = m[3] === undefined ? 0 : parseInt(m[3], 10);
  const millis = m[4] === undefined ? 0 : parseInt((m[4] + "00").slice(0, 3), 10);

  if (hour === 24) {
    // 24:00:00 denotes the end of the day only.
    if (minute !== 0 || second !== 0 || millis !== 0) return null;
  } else if (hour > 23) {
    return null;
  }
  if (minute > 59) return null;
  if (second > 60) return null; // 60 is a leap second, validated by the caller

  let offsetMs = 0;
  const zone = m[5];
  if (zone !== undefined && zone !== "Z") {
    const digits = zone.slice(1).replace(":", "");
    const oh = parseInt(digits.slice(0, 2), 10);
    const om = digits.length > 2 ? parseInt(digits.slice(2, 4), 10) : 0;
    if (oh > 23 || om > 59) return null;
    const sign = zone[0] === "-" ? -1 : 1;
    offsetMs = sign * (oh * 3600 + om * 60) * 1000;
  }

  return { hour, minute, second, millis, offsetMs };
}

function parseStamp(input: unknown): number {
  const bad = (): never => {
    throw new RangeError(`Invalid ISO 8601 date or date-time: ${JSON.stringify(input)}`);
  };
  if (typeof input !== "string") return bad();
  const s: string = input;

  const tIdx = s.indexOf("T");
  const datePart = tIdx < 0 ? s : s.slice(0, tIdx);
  const timePart = tIdx < 0 ? undefined : s.slice(tIdx + 1);

  const date = parseDate(datePart);
  if (!date) return bad();

  const dayMs = daysFromCivil(date.year, date.month, date.day) * DAY_MS;

  if (timePart === undefined) {
    // Date only: interpreted as midnight UTC.
    if (!(Math.abs(dayMs) <= MAX_MS)) return bad();
    return dayMs;
  }

  // Date-time requires a complete date and a date/time representation style
  // that matches (basic or extended throughout).
  if (!date.complete) return bad();
  const time = parseTime(timePart, date.style);
  if (!time) return bad();

  const result =
    dayMs +
    ((time.hour * 60 + time.minute) * 60 + time.second) * 1000 +
    time.millis -
    time.offsetMs;

  if (time.second === 60) {
    // A leap second is only valid at the end of June or December (UTC).
    const jul1 = daysFromCivil(date.year, 7, 1) * DAY_MS;
    const jan1Next = daysFromCivil(date.year + 1, 1, 1) * DAY_MS;
    if (result !== jul1 && result !== jan1Next) return bad();
  }

  if (!(Math.abs(result) <= MAX_MS)) return bad();
  return result;
}

export function solve(stamps: string[]): number[] {
  if (!Array.isArray(stamps)) {
    throw new RangeError("Expected an array of ISO 8601 strings");
  }
  return stamps.map((x) => parseStamp(x)).sort((a, b) => a - b);
}

export function solve(version: string, kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease', id?: string): string | null {
  return lib.inc(version, kind, id);
}

type Id = number | string;

// Mirrors node-semver 7's FULL grammar: optional leading "v", no build in output,
// strict numeric identifiers, optional prerelease and build.
const FULL =
  /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][a-zA-Z0-9-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][a-zA-Z0-9-]*))*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;

// Identifier validation used for the `id` argument of pre* kinds.
const PRE_ID_LIST =
  /^(?:0|[1-9]\d*|\d*[a-zA-Z-][a-zA-Z0-9-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][a-zA-Z0-9-]*))*$/;

const NUMERIC = /^[0-9]+$/;

function isNumericId(x: Id | undefined): boolean {
  return x !== undefined && NUMERIC.test(String(x));
}

// Mirrors node-semver's compareIdentifiers.
function compareIds(a: Id | undefined, b: Id): number {
  const an = isNumericId(a);
  const bn = isNumericId(b);
  let x: any = a;
  let y: any = b;
  if (an && bn) {
    x = Number(a);
    y = Number(b);
  }
  if (x === y) return 0;
  if (an && !bn) return -1;
  if (bn && !an) return 1;
  return x < y ? -1 : 1;
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  try {
    if (typeof version !== 'string' || version.length > 256) return null;

    const m = version.trim().match(FULL);
    if (!m) return null;

    const MAX = Number.MAX_SAFE_INTEGER;
    let major = Number(m[1]);
    let minor = Number(m[2]);
    let patch = Number(m[3]);
    if (major > MAX || minor > MAX || patch > MAX) return null;

    let pre: Id[] = m[4]
      ? m[4].split('.').map((p): Id => {
          if (NUMERIC.test(p)) {
            const num = Number(p);
            if (num >= 0 && num < MAX) return num;
          }
          return p;
        })
      : [];

    // Pre* kinds validate the identifier before doing anything else.
    if (kind.startsWith('pre') && id) {
      if (!PRE_ID_LIST.test(id)) return null;
    }

    const step = (rel: string): void => {
      switch (rel) {
        case 'premajor':
          pre = [];
          patch = 0;
          minor = 0;
          major++;
          step('pre');
          break;

        case 'preminor':
          pre = [];
          patch = 0;
          minor++;
          step('pre');
          break;

        case 'prepatch':
          pre = [];
          step('patch');
          step('pre');
          break;

        case 'prerelease':
          if (pre.length === 0) step('patch');
          step('pre');
          break;

        case 'major':
          if (minor !== 0 || patch !== 0 || pre.length === 0) major++;
          minor = 0;
          patch = 0;
          pre = [];
          break;

        case 'minor':
          if (patch !== 0 || pre.length === 0) minor++;
          patch = 0;
          pre = [];
          break;

        case 'patch':
          if (pre.length === 0) patch++;
          pre = [];
          break;

        case 'pre': {
          const base = 0;
          if (pre.length === 0) {
            pre = [base];
          } else {
            let i = pre.length;
            while (--i >= 0) {
              const v = pre[i];
              if (typeof v === 'number') {
                pre[i] = v + 1;
                i = -2;
              }
            }
            if (i === -1) pre.push(base);
          }

          if (id) {
            const np: Id[] = [id, base];
            if (compareIds(pre[0], id) === 0) {
              if (Number.isNaN(Number(pre[1]))) pre = np;
            } else {
              pre = np;
            }
          }
          break;
        }

        default:
          throw new Error('invalid increment argument: ' + rel);
      }
    };

    step(kind);

    return `${major}.${minor}.${patch}` + (pre.length ? '-' + pre.join('.') : '');
  } catch {
    return null;
  }
}

export function solve(versions: string[]): string[] {
  // lib.sort sorts in place, so sort a copy to return a new array
  // and leave the input unchanged.
  return lib.sort([...versions]);
}

export function solve(text: string): string | null {
  const v = lib.coerce(text);
  if (v === null) {
    return null;
  }
  return `${v.major}.${v.minor}.${v.patch}`;
}

export function solve(a: string, b: string): string | null {
  return lib.diff(a, b);
}

export function solve(uuid: string): string | null {
    // Canonical 8-4-4-4-12 hex form, either case, version nibble 1, RFC 9562 variant (10xx in byte 8).
    const pattern = /^[0-9a-f]{8}-[0-9a-f]{4}-1[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    if (typeof uuid !== 'string' || !pattern.test(uuid)) {
        return null;
    }
    const v6 = lib.v1ToV6(uuid.toLowerCase());
    return String(v6).toLowerCase();
}

export function solve(id: string): boolean {
  const cleaned = id.replace(/[\/\\]/g, '');
  return lib.isTaxID(cleaned, 'de-DE');
}

const MS_PER_DAY = 86400000;
const MS_PER_HOUR = 3600000;
const MS_PER_MINUTE = 60000;
const MS_PER_SECOND = 1000;
const MAX_EPOCH_MS = 8.64e15; // ECMAScript time value limit

const YEAR = "([+-]\\d{6}|\\d{4})";

type Groups = (string | undefined)[];

interface DateForm {
  re: RegExp;
  ext: boolean;   // extended (separator) format?
  full: boolean;  // complete date (day-level precision)?
  build: (year: number, g: Groups) => number | null; // returns days since epoch
}

interface ParsedDate {
  days: number;
  ext: boolean;
  full: boolean;
}

function invalid(input: unknown): never {
  throw new RangeError(`Invalid ISO 8601 date/date-time: ${String(input)}`);
}

function isLeapYear(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  return [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
}

/** Days since 1970-01-01 in the proleptic Gregorian calendar, valid for any integer year. */
function daysFromCivil(y: number, m: number, d: number): number {
  const yy = m <= 2 ? y - 1 : y;
  const era = Math.floor(yy / 400);
  const yoe = yy - era * 400;
  const mp = (m + 9) % 12; // March = 0
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

/** 0 = Monday ... 6 = Sunday (1970-01-01 was a Thursday). */
function weekdayIndex(days: number): number {
  return (((days + 3) % 7) + 7) % 7;
}

/** ISO 8601: a week-numbering year has 53 weeks if p(y) = 4 or p(y-1) = 3. */
function weeksInYear(y: number): number {
  const p = (x: number): number =>
    (((x + Math.floor(x / 4) - Math.floor(x / 100) + Math.floor(x / 400)) % 7) + 7) % 7;
  return p(y) === 4 || p(y - 1) === 3 ? 53 : 52;
}

function parseYear(s: string): number | null {
  if (s[0] === "+" || s[0] === "-") {
    if (s === "-000000") return null; // ISO forbids negative zero year
    const n = parseInt(s.slice(1), 10);
    return s[0] === "-" ? -n : n;
  }
  return parseInt(s, 10);
}

function calendarDay(y: number, m: number, d: number): number | null {
  if (m < 1 || m > 12) return null;
  if (d < 1 || d > daysInMonth(y, m)) return null;
  return daysFromCivil(y, m, d);
}

function ordinalDay(y: number, n: number): number | null {
  const max = isLeapYear(y) ? 366 : 365;
  if (n < 1 || n > max) return null;
  return daysFromCivil(y, 1, 1) + n - 1;
}

function weekDay(y: number, w: number, d: number): number | null {
  if (w < 1 || w > weeksInYear(y)) return null;
  if (d < 1 || d > 7) return null;
  const jan4 = daysFromCivil(y, 1, 4);
  const monWeek1 = jan4 - weekdayIndex(jan4);
  return monWeek1 + (w - 1) * 7 + (d - 1);
}

const DATE_FORMS: DateForm[] = [
  // Calendar, extended: YYYY-MM-DD
  {
    re: new RegExp(`^${YEAR}-(\\d{2})-(\\d{2})$`), ext: true, full: true,
    build: (y, g) => calendarDay(y, Number(g[2]), Number(g[3])),
  },
  // Calendar, basic: YYYYMMDD
  {
    re: new RegExp(`^${YEAR}(\\d{2})(\\d{2})$`), ext: false, full: true,
    build: (y, g) => calendarDay(y, Number(g[2]), Number(g[3])),
  },
  // Ordinal, extended: YYYY-DDD
  {
    re: new RegExp(`^${YEAR}-(\\d{3})$`), ext: true, full: true,
    build: (y, g) => ordinalDay(y, Number(g[2])),
  },
  // Ordinal, basic: YYYYDDD
  {
    re: new RegExp(`^${YEAR}(\\d{3})$`), ext: false, full: true,
    build: (y, g) => ordinalDay(y, Number(g[2])),
  },
  // Week, extended: YYYY-Www-D
  {
    re: new RegExp(`^${YEAR}-W(\\d{2})-(\\d)$`), ext: true, full: true,
    build: (y, g) => weekDay(y, Number(g[2]), Number(g[3])),
  },
  // Week, extended, reduced: YYYY-Www
  {
    re: new RegExp(`^${YEAR}-W(\\d{2})$`), ext: true, full: false,
    build: (y, g) => weekDay(y, Number(g[2]), 1),
  },
  // Week, basic: YYYYWwwD
  {
    re: new RegExp(`^${YEAR}W(\\d{2})(\\d)$`), ext: false, full: true,
    build: (y, g) => weekDay(y, Number(g[2]), Number(g[3])),
  },
  // Week, basic, reduced: YYYYWww
  {
    re: new RegExp(`^${YEAR}W(\\d{2})$`), ext: false, full: false,
    build: (y, g) => weekDay(y, Number(g[2]), 1),
  },
  // Calendar month, reduced: YYYY-MM
  {
    re: new RegExp(`^${YEAR}-(\\d{2})$`), ext: true, full: false,
    build: (y, g) => calendarDay(y, Number(g[2]), 1),
  },
  // Year only: YYYY
  {
    re: new RegExp(`^${YEAR}$`), ext: false, full: false,
    build: (y) => calendarDay(y, 1, 1),
  },
];

// Time with optional fraction (lowest-order component) and optional offset.
const EXT_TIME = /^(\d{2})(?::(\d{2})(?::(\d{2}))?)?([.,]\d+)?(Z|[+-]\d{2}(?::?\d{2})?)?$/;
const BASIC_TIME = /^(\d{2})(?:(\d{2})(?:(\d{2}))?)?([.,]\d+)?(Z|[+-]\d{2}(?::?\d{2})?)?$/;

function parseDatePart(s: string): ParsedDate | null {
  for (const form of DATE_FORMS) {
    const g = form.re.exec(s);
    if (!g) continue;
    const year = parseYear(g[1]);
    if (year === null) return null;
    const days = form.build(year, g);
    return days === null ? null : { days, ext: form.ext, full: form.full };
  }
  return null;
}

/** Returns milliseconds since start of day (local to the given offset) and the offset in minutes. */
function parseTimePart(g: Groups): { msOfDay: number; offsetMin: number } | null {
  const hour = Number(g[1]);
  const hasMin = g[2] !== undefined;
  const hasSec = g[3] !== undefined;
  const minute = hasMin ? Number(g[2]) : 0;
  const second = hasSec ? Number(g[3]) : 0;

  // Unit of the lowest-order component, which carries any decimal fraction.
  const unit = !hasMin ? MS_PER_HOUR : !hasSec ? MS_PER_MINUTE : MS_PER_SECOND;

  let frac = 0;
  let fracNonZero = false;
  if (g[4] !== undefined) {
    const digits = g[4].slice(1);
    const n = Number((digits + "000000000").slice(0, 9)); // up to 9 digits (sub-ns truncated)
    fracNonZero = n > 0;
    frac = Math.floor((n * unit) / 1e9);
  }

  if (hour > 24 || minute > 59 || second > 60) return null;
  // 24:00 is only valid as the end of the day.
  if (hour === 24 && (minute !== 0 || second !== 0 || fracNonZero)) return null;

  const msOfDay =
    hour * MS_PER_HOUR + minute * MS_PER_MINUTE + second * MS_PER_SECOND + frac;

  let offsetMin = 0;
  if (g[5] !== undefined && g[5] !== "Z") {
    const o = /^([+-])(\d{2}):?(\d{2})?$/.exec(g[5]);
    if (!o) return null;
    const oh = Number(o[2]);
    const om = o[3] === undefined ? 0 : Number(o[3]);
    if (oh > 23 || om > 59) return null;
    offsetMin = (o[1] === "-" ? -1 : 1) * (oh * 60 + om);
  }

  return { msOfDay, offsetMin };
}

function parseStamp(input: unknown): number {
  if (typeof input !== "string") return invalid(input);

  const t = input.indexOf("T");
  const datePart = t === -1 ? input : input.slice(0, t);
  const date = parseDatePart(datePart);
  if (date === null) return invalid(input);

  let epoch: number;
  if (t === -1) {
    // Date only: interpreted as UTC midnight.
    epoch = date.days * MS_PER_DAY;
  } else {
    // A date-time requires a complete date.
    if (!date.full) return invalid(input);

    const timeRe = date.ext ? EXT_TIME : BASIC_TIME;
    const g = timeRe.exec(input.slice(t + 1));
    if (!g) return invalid(input);

    const time = parseTimePart(g);
    if (time === null) return invalid(input);

    epoch =
      date.days * MS_PER_DAY + time.msOfDay - time.offsetMin * MS_PER_MINUTE;
  }

  if (!Number.isFinite(epoch) || Math.abs(epoch) > MAX_EPOCH_MS) {
    return invalid(input);
  }
  return epoch;
}

export function solve(stamps: string[]): number[] {
  if (!Array.isArray(stamps)) {
    throw new RangeError("Expected an array of ISO 8601 strings");
  }
  const values = stamps.map((s) => parseStamp(s));
  values.sort((a, b) => a - b);
  return values;
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;

  const s = code.toUpperCase();

  // Exactly 4 letters (3 owner letters + equipment category), 6 serial digits, 1 check digit.
  if (!/^[A-Z]{4}\d{7}$/.test(s)) return false;

  // Equipment category identifier must be U, J, or Z.
  if (!"UJZ".includes(s[3])) return false;

  // ISO 6346 letter values: A=10, B=12, ..., skipping multiples of 11 (11, 22, 33).
  const letterValues: Record<string, number> = {};
  let v = 10;
  for (const ch of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") {
    if (v % 11 === 0) v++;
    letterValues[ch] = v;
    v++;
  }

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const c = s[i];
    const value = /\d/.test(c) ? Number(c) : letterValues[c];
    sum += value * Math.pow(2, i);
  }

  const check = (sum % 11) % 10;
  return check === Number(s[10]);
}

export function solve(text: string): string | null {
  // Same pattern node-semver 7 uses for coerce() with default options.
  const COERCE = /(^|[^\d])(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?:$|[^\d])/;
  const MAX_SAFE_INTEGER = 9007199254740991;

  const match = COERCE.exec(text);
  if (match === null) return null;

  const major = match[2];
  const minor = match[3] === undefined ? "0" : match[3];
  const patch = match[4] === undefined ? "0" : match[4];

  // node-semver's strict parse rejects leading zeros and values above MAX_SAFE_INTEGER.
  const isValid = (s: string): boolean =>
    (s === "0" || /^[1-9]\d*$/.test(s)) && Number(s) <= MAX_SAFE_INTEGER;

  if (!isValid(major) || !isValid(minor) || !isValid(patch)) return null;

  return `${major}.${minor}.${patch}`;
}

type Parsed = {
  major: string;
  minor: string;
  patch: string;
  pre: string[];
};

const SEMVER_RE =
  /^\s*v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?\s*$/;

function parse(v: string): Parsed {
  const m = SEMVER_RE.exec(v);
  if (!m) {
    throw new TypeError(`Invalid semver version: ${v}`);
  }
  return {
    major: m[1],
    minor: m[2],
    patch: m[3],
    pre: m[4] ? m[4].split(".") : [],
  };
}

// Compare canonical non-negative integer strings (no leading zeros).
function cmpNumeric(x: string, y: string): number {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function cmpPreIdentifier(x: string, y: string): number {
  const xNum = /^\d+$/.test(x);
  const yNum = /^\d+$/.test(y);
  if (xNum && yNum) return cmpNumeric(x, y);
  if (xNum) return -1; // numeric identifiers sort before alphanumeric
  if (yNum) return 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function cmpPre(a: string[], b: string[]): number {
  // A version without prerelease has higher precedence.
  if (a.length === 0 && b.length === 0) return 0;
  if (a.length === 0) return 1;
  if (b.length === 0) return -1;

  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const c = cmpPreIdentifier(a[i], b[i]);
    if (c !== 0) return c;
  }
  if (a.length === b.length) return 0;
  return a.length < b.length ? -1 : 1;
}

function cmpMain(a: Parsed, b: Parsed): number {
  return (
    cmpNumeric(a.major, b.major) ||
    cmpNumeric(a.minor, b.minor) ||
    cmpNumeric(a.patch, b.patch)
  );
}

function cmpVersions(a: Parsed, b: Parsed): number {
  return cmpMain(a, b) || cmpPre(a.pre, b.pre);
}

export function solve(a: string, b: string): string | null {
  const v1 = parse(a);
  const v2 = parse(b);

  const comparison = cmpVersions(v1, v2);
  if (comparison === 0) {
    return null;
  }

  const v1Higher = comparison > 0;
  const high = v1Higher ? v1 : v2;
  const low = v1Higher ? v2 : v1;
  const highHasPre = high.pre.length > 0;
  const lowHasPre = low.pre.length > 0;

  if (lowHasPre && !highHasPre) {
    // Prerelease -> release needs special handling.
    // If the low version has only a major part, the change is always major.
    if (low.minor === "0" && low.patch === "0") {
      return "major";
    }

    // If the main part (major.minor.patch) is identical.
    if (cmpMain(high, low) === 0) {
      if (low.minor !== "0" && low.patch === "0") {
        return "minor";
      }
      return "patch";
    }
  }

  // Add the "pre" prefix when the higher version is a prerelease.
  const prefix = highHasPre ? "pre" : "";

  if (v1.major !== v2.major) {
    return prefix + "major";
  }

  if (v1.minor !== v2.minor) {
    return prefix + "minor";
  }

  if (v1.patch !== v2.patch) {
    return prefix + "patch";
  }

  // Same major.minor.patch, differing only in prerelease.
  return "prerelease";
}

export function solve(stamps: string[]): number[] {
  const toEpochMs = (s: string): number => {
    // The library's no-offset branch interprets the wall-clock fields in the
    // local time zone (setHours/setFullYear), which breaks the UTC requirement
    // and can shift times across DST gaps. Appending "Z" forces the library's
    // offset branch, which computes the timestamp directly in UTC. If the input
    // already carries an offset, the suffixed string is malformed (e.g. "+02:00Z"
    // or "ZZ") and is rejected, so we fall back to the explicit parse.
    const utc = lib.parseISO(s + "Z");
    if (!isNaN(utc.getTime())) return utc.getTime();

    const explicit = lib.parseISO(s);
    if (!isNaN(explicit.getTime())) return explicit.getTime();

    throw new RangeError(`Invalid ISO 8601 date string: ${JSON.stringify(s)}`);
  };

  return stamps.map(toEpochMs).sort((a, b) => a - b);
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const s = id.replace(/[\/\\]/g, "");

  // Exactly 11 digits, first digit must not be 0
  if (!/^[1-9][0-9]{10}$/.test(s)) return false;

  const digits = s.split("").map(Number);

  // Rule on repeated digits among the first 10 digits:
  // no digit may appear more than 3 times, and exactly one digit
  // must appear 2 or 3 times (all other digits at most once).
  const counts = new Array<number>(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[digits[i]]++;
  }
  if (counts.some((c) => c > 3)) return false;
  const repeated = counts.filter((c) => c === 2 || c === 3).length;
  if (repeated !== 1) return false;

  // Check digit (ISO 7064 Mod 11,10 as specified for the Steuer-IdNr.)
  let product = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (digits[i] + product) % 10;
    if (sum === 0) sum = 10;
    product = (sum * 2) % 11;
  }
  let check = 11 - product;
  if (check === 10) check = 0;

  return check === digits[10];
}

export function solve(code: string): boolean {
  const upper = code.toUpperCase();
  // Owner code (3 letters), equipment category (U, J or Z), serial number (6 digits), check digit (1 digit)
  if (!/^[A-Z]{3}[UJZ]\d{7}$/.test(upper)) return false;
  return lib.isISO6346(upper);
}

export function solve(uuid: string): string | null {
  // Canonical 8-4-4-4-12 form, version nibble must be 1, variant must be RFC 9562 (10xx).
  const m = /^([0-9a-f]{8})-([0-9a-f]{4})-1([0-9a-f]{3})-([89ab][0-9a-f]{3})-([0-9a-f]{12})$/i.exec(uuid);
  if (m === null) {
    return null;
  }

  const timeLow = m[1];
  const timeMid = m[2];
  const timeHi = m[3];
  const clockSeq = m[4];
  const node = m[5];

  // 60-bit timestamp as 15 hex digits: time_hi (12 bits) | time_mid (16 bits) | time_low (32 bits)
  const t = timeHi + timeMid + timeLow;

  // RFC 9562 v6 layout: time_high (32) | time_mid (16) | version (4) + time_low_12 (12) | clock_seq | node
  const timeHigh = t.slice(0, 8);
  const timeMid6 = t.slice(8, 12);
  const timeLow6 = "6" + t.slice(12, 15);

  return `${timeHigh}-${timeMid6}-${timeLow6}-${clockSeq}-${node}`.toLowerCase();
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  return lib.inc(version, kind, id);
}

type ReleaseKind =
  | 'major'
  | 'minor'
  | 'patch'
  | 'premajor'
  | 'preminor'
  | 'prepatch'
  | 'prerelease';

const MAX_LENGTH = 256;
const MAX_SAFE = Number.MAX_SAFE_INTEGER;

const NUMERIC = '0|[1-9]\\d*';
const NON_NUMERIC = '\\d*[a-zA-Z-][a-zA-Z0-9-]*';
const PRE_ID = `(?:${NUMERIC}|${NON_NUMERIC})`;
const PRE = `(?:-(${PRE_ID}(?:\\.${PRE_ID})*))`;
const BUILD = `(?:\\+([0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*))`;
const FULL_RE = new RegExp(
  `^v?(${NUMERIC})\\.(${NUMERIC})\\.(${NUMERIC})${PRE}?${BUILD}?$`
);
const NUMERIC_ID_RE = /^[0-9]+$/;

type PreId = string | number;

function compareIdentifiers(a: PreId, b: PreId): number {
  const as = String(a);
  const bs = String(b);
  const anum = NUMERIC_ID_RE.test(as);
  const bnum = NUMERIC_ID_RE.test(bs);
  if (anum && bnum) {
    const x = Number(as);
    const y = Number(bs);
    return x === y ? 0 : x < y ? -1 : 1;
  }
  if (anum) return -1;
  if (bnum) return 1;
  return as === bs ? 0 : as < bs ? -1 : 1;
}

export function solve(
  version: string,
  kind: ReleaseKind,
  id?: string
): string | null {
  if (typeof version !== 'string' || version.length > MAX_LENGTH) return null;

  const m = version.trim().match(FULL_RE);
  if (!m) return null;

  let major = Number(m[1]);
  let minor = Number(m[2]);
  let patch = Number(m[3]);
  if (major > MAX_SAFE || minor > MAX_SAFE || patch > MAX_SAFE) return null;

  let pre: PreId[] = m[4]
    ? m[4].split('.').map((part): PreId => {
        if (NUMERIC_ID_RE.test(part)) {
          const num = Number(part);
          if (num >= 0 && num < MAX_SAFE) return num;
        }
        return part;
      })
    : [];

  // Equivalent of SemVer#inc('pre', identifier) with identifierBase undefined
  // (so the base is 0).
  const incPre = (identifier: string | undefined): void => {
    const base = 0;
    if (pre.length === 0) {
      pre = [base];
    } else {
      let found = false;
      for (let i = pre.length - 1; i >= 0; i--) {
        const cur = pre[i];
        if (typeof cur === 'number') {
          pre[i] = cur + 1;
          found = true;
          break;
        }
      }
      if (!found) pre.push(base);
    }

    if (identifier) {
      const next: PreId[] = [identifier, base];
      if (pre.length > 0 && compareIdentifiers(pre[0], identifier) === 0) {
        if (Number.isNaN(Number(pre[1]))) {
          pre = next;
        }
      } else {
        pre = next;
      }
    }
  };

  switch (kind) {
    case 'premajor':
      pre = [];
      patch = 0;
      minor = 0;
      major++;
      incPre(id);
      break;
    case 'preminor':
      pre = [];
      patch = 0;
      minor++;
      incPre(id);
      break;
    case 'prepatch':
      pre = [];
      patch++;
      incPre(id);
      break;
    case 'prerelease':
      if (pre.length === 0) patch++;
      incPre(id);
      break;
    case 'major':
      if (minor !== 0 || patch !== 0 || pre.length === 0) major++;
      minor = 0;
      patch = 0;
      pre = [];
      break;
    case 'minor':
      if (patch !== 0 || pre.length === 0) minor++;
      patch = 0;
      pre = [];
      break;
    case 'patch':
      if (pre.length === 0) patch++;
      pre = [];
      break;
    default:
      return null;
  }

  let out = `${major}.${minor}.${patch}`;
  if (pre.length > 0) out += '-' + pre.map(String).join('.');
  return out;
}

type Parsed = {
  major: string;
  minor: string;
  patch: string;
  pre: string[];
  build: string[];
};

const SEMVER_RE =
  /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;

const NUMERIC = /^[0-9]+$/;

function parse(raw: string): Parsed | null {
  const m = SEMVER_RE.exec(raw.trim());
  if (!m) return null;
  return {
    major: m[1],
    minor: m[2],
    patch: m[3],
    pre: m[4] ? m[4].split(".") : [],
    build: m[5] ? m[5].split(".") : [],
  };
}

// Exact numeric comparison of digit strings (no precision loss).
function cmpNumeric(a: string, b: string): number {
  const x = a.replace(/^0+(?=\d)/, "");
  const y = b.replace(/^0+(?=\d)/, "");
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  return x === y ? 0 : x < y ? -1 : 1;
}

// Identifier comparison: numeric identifiers compare numerically and sort
// before alphanumeric ones; otherwise lexical comparison.
function cmpIdent(a: string, b: string): number {
  const an = NUMERIC.test(a);
  const bn = NUMERIC.test(b);
  if (an && bn) return cmpNumeric(a, b);
  if (an !== bn) return an ? -1 : 1;
  return a === b ? 0 : a < b ? -1 : 1;
}

// Element-wise list comparison; a longer list with an equal prefix is greater.
function cmpList(a: string[], b: string[]): number {
  let i = 0;
  for (;;) {
    const x = a[i];
    const y = b[i];
    if (x === undefined && y === undefined) return 0;
    if (y === undefined) return 1;
    if (x === undefined) return -1;
    if (x !== y) return cmpIdent(x, y);
    i++;
  }
}

// Prerelease: a version without prerelease has higher precedence.
function cmpPre(a: string[], b: string[]): number {
  if (a.length === 0 && b.length === 0) return 0;
  if (a.length === 0) return 1;
  if (b.length === 0) return -1;
  return cmpList(a, b);
}

function compare(a: Parsed, b: Parsed): number {
  return (
    cmpNumeric(a.major, b.major) ||
    cmpNumeric(a.minor, b.minor) ||
    cmpNumeric(a.patch, b.patch) ||
    cmpPre(a.pre, b.pre)
  );
}

function compareBuild(a: Parsed, b: Parsed): number {
  return compare(a, b) || cmpList(a.build, b.build);
}

export function solve(versions: string[]): string[] {
  const entries: { raw: string; v: Parsed }[] = [];
  for (const raw of versions) {
    const v = parse(raw);
    if (v) entries.push({ raw, v });
  }
  // Array.prototype.sort is stable, so fully equal entries keep input order.
  entries.sort((x, y) => compareBuild(x.v, y.v));
  return entries.map((e) => e.raw);
}

export function solve(a: string, b: string): string | null {
  return lib.diff(a, b);
}

export function solve(versions: string[]): string[] {
  // lib.sort sorts in place, so sort a copy to return a new array.
  return lib.sort([...versions]);
}

export function solve(text: string): string | null {
  const v = lib.coerce(text);
  if (v === null || v === undefined) {
    return null;
  }
  return `${v.major}.${v.minor}.${v.patch}`;
}

type Kind = "cal" | "week" | "ord";

interface Form {
  kind: Kind;
  groups: number; // capture groups in the date part (year is group 1)
  re: RegExp;
}

const DAY_MS = 86400000;
const MIN_MS = 60000;

// Year: 4 digits, or sign + 6 digits (expanded representation)
const YEAR = String.raw`([+-]\d{6}|\d{4})`;

// Time: hh, hh:mm, hh:mm:ss, hh:mm:ss.fff (or ',' as decimal sign); fraction only on seconds
const TIME_EXT = String.raw`(\d{2})(?::(\d{2})(?::(\d{2})(?:[.,](\d+))?)?)?`;
const TIME_BAS = String.raw`(\d{2})(?:(\d{2})(?:(\d{2})(?:[.,](\d+))?)?)?`;

// Offset: Z, or ±hh, ±hh:mm (extended) / ±hhmm (basic)
const OFF_EXT = String.raw`([Zz]|[+-]\d{2}(?::\d{2})?)`;
const OFF_BAS = String.raw`([Zz]|[+-]\d{2}(?:\d{2})?)`;

function form(kind: Kind, groups: number, date: string, time: string, off: string): Form {
  return {
    kind,
    groups,
    re: new RegExp(`^${date}(?:[Tt]${time}(?:${off})?)?$`),
  };
}

// Extended and basic formats are kept separate so mixing them is rejected.
const FORMS: Form[] = [
  // Extended
  form("cal", 3, String.raw`${YEAR}(?:-(\d{2})(?:-(\d{2}))?)?`, TIME_EXT, OFF_EXT),
  form("week", 3, String.raw`${YEAR}-W(\d{2})(?:-(\d))?`, TIME_EXT, OFF_EXT),
  form("ord", 2, String.raw`${YEAR}-(\d{3})`, TIME_EXT, OFF_EXT),
  // Basic
  form("cal", 3, String.raw`${YEAR}(?:(\d{2})(\d{2}))?`, TIME_BAS, OFF_BAS),
  form("week", 3, String.raw`${YEAR}W(\d{2})(\d)?`, TIME_BAS, OFF_BAS),
  form("ord", 2, String.raw`${YEAR}(\d{3})`, TIME_BAS, OFF_BAS),
];

function fail(what: string): never {
  throw new RangeError(`Invalid ISO 8601 ${what}`);
}

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, month: number): number {
  return [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
}

/** Number of ISO weeks (52 or 53) in ISO week-numbering year y. */
function isoWeeksInYear(y: number): number {
  const p = (x: number): number => {
    const v = x + Math.floor(x / 4) - Math.floor(x / 100) + Math.floor(x / 400);
    return ((v % 7) + 7) % 7;
  };
  return p(y) === 4 || p(y - 1) === 3 ? 53 : 52;
}

/** Epoch ms of 00:00:00Z on the given calendar day (NaN if out of range). */
function utcDay(y: number, month0: number, day: number): number {
  const d = new Date(0);
  d.setUTCFullYear(y, month0, day);
  return d.getTime();
}

function toEpoch(f: Form, m: readonly (string | undefined)[]): number {
  // Year
  const ys = m[1] as string;
  const sign = ys[0] === "-" ? -1 : 1;
  const digits = ys.length === 4 ? ys : ys.slice(1);
  if (sign < 0 && Number(digits) === 0) fail("year: -000000");
  const year = sign * Number(digits);

  // Date part
  let dayStart: number;
  if (f.kind === "cal") {
    const month = m[2] === undefined ? 1 : Number(m[2]);
    const day = m[3] === undefined ? 1 : Number(m[3]);
    if (month < 1 || month > 12) fail(`month: ${m[0]}`);
    if (day < 1 || day > daysInMonth(year, month)) fail(`day: ${m[0]}`);
    dayStart = utcDay(year, month - 1, day);
  } else if (f.kind === "ord") {
    const doy = Number(m[2]);
    if (doy < 1 || doy > (isLeap(year) ? 366 : 365)) fail(`ordinal date: ${m[0]}`);
    dayStart = utcDay(year, 0, 1) + (doy - 1) * DAY_MS;
  } else {
    const week = Number(m[2]);
    const wd = m[3] === undefined ? 1 : Number(m[3]);
    if (week < 1 || week > isoWeeksInYear(year)) fail(`week date: ${m[0]}`);
    if (wd < 1 || wd > 7) fail(`weekday: ${m[0]}`);
    const jan4 = utcDay(year, 0, 4);
    const isoDow = new Date(jan4).getUTCDay() || 7; // Mon=1 .. Sun=7
    const monday = jan4 - (isoDow - 1) * DAY_MS;
    dayStart = monday + ((week - 1) * 7 + (wd - 1)) * DAY_MS;
  }

  // Time part (optional); no time means midnight UTC
  let epoch = dayStart;
  const g = f.groups;
  if (m[g + 1] !== undefined) {
    const h = Number(m[g + 1]);
    const mi = m[g + 2] === undefined ? 0 : Number(m[g + 2]);
    const sec = m[g + 3] === undefined ? 0 : Number(m[g + 3]);
    const frac = m[g + 4] ?? "";
    const offStr = m[g + 5];

    if (mi > 59) fail(`time: ${m[0]}`);
    if (h === 24) {
      // 24:00[:00[.0]] denotes the end of the day
      if (mi !== 0 || sec !== 0 || /[1-9]/.test(frac)) fail(`time: ${m[0]}`);
    } else if (h > 23) {
      fail(`time: ${m[0]}`);
    }
    if (sec > 60) fail(`time: ${m[0]}`);

    let offMin = 0;
    if (offStr !== undefined && offStr !== "Z" && offStr !== "z") {
      const osign = offStr[0] === "-" ? -1 : 1;
      const od = offStr.slice(1).replace(":", "");
      const oh = Number(od.slice(0, 2));
      const om = od.length > 2 ? Number(od.slice(2)) : 0;
      if (oh > 23 || om > 59) fail(`offset: ${m[0]}`);
      offMin = osign * (oh * 60 + om);
    }

    // Leap second is only valid at 23:59:60 UTC
    if (sec === 60) {
      const utcMinOfDay = (((h * 60 + mi - offMin) % 1440) + 1440) % 1440;
      if (utcMinOfDay !== 1439) fail(`leap second: ${m[0]}`);
    }

    const ms = frac === "" ? 0 : Number((frac + "00").slice(0, 3));
    epoch = dayStart + (((h * 60 + mi) * 60 + sec) * 1000 + ms) - offMin * MIN_MS;
  }

  if (!Number.isFinite(epoch) || Math.abs(epoch) > 8.64e15) {
    fail(`date (out of range): ${m[0]}`);
  }
  return epoch;
}

function parseOne(s: string): number {
  if (typeof s !== "string") {
    throw new RangeError(`Invalid ISO 8601 date: ${String(s)}`);
  }
  for (const f of FORMS) {
    const m = f.re.exec(s);
    if (m !== null) return toEpoch(f, m);
  }
  throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(s)}`);
}

export function solve(stamps: string[]): number[] {
  return stamps.map((s) => parseOne(s)).sort((a, b) => a - b);
}

export function solve(uuid: string): string | null {
    if (typeof uuid !== 'string') {
        return null;
    }

    // Canonical 8-4-4-4-12 hex form, either case.
    // Third group must start with version nibble 1 (version-1 input).
    // Fourth group must start with RFC 9562 variant bits 10xxxxxx (8, 9, a, b).
    const pattern =
        /^[0-9a-f]{8}-[0-9a-f]{4}-1[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    if (!pattern.test(uuid)) {
        return null;
    }

    return lib.v1ToV6(uuid.toLowerCase()) as string;
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes
  const cleaned = id.replace(/[\/\\]/g, '');

  // Format (11 digits, first digit not 0) and check digit via the library
  if (!lib.isTaxID(cleaned, 'de-DE')) {
    return false;
  }

  const digits = cleaned.split('').map(Number);

  // Repeated-digit rule: among the first 10 digits, exactly one digit
  // occurs 2 or 3 times, and no digit occurs more than 3 times
  const counts = new Array<number>(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[digits[i]]++;
  }
  let repeatedCount = 0;
  let tooMany = false;
  for (const c of counts) {
    if (c === 2 || c === 3) {
      repeatedCount++;
    } else if (c > 3) {
      tooMany = true;
    }
  }
  if (tooMany || repeatedCount !== 1) {
    return false;
  }

  // Check digit (ISO 7064 Mod 11,10) over the first 10 digits
  let product = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (digits[i] + product) % 10;
    if (sum === 0) {
      sum = 10;
    }
    product = (sum * 2) % 11;
  }
  const check = (11 - product) % 10;

  return check === digits[10];
}

// `lib` is the pre-existing global exposing parseISO; this is a type-only declaration.
declare const lib: {
  parseISO(argument: string, options?: unknown): Date;
};

// Date portion: optional sign, then digits, 'W' and '-' only (basic or extended forms).
const DATE_PART = /^[+-]?[0-9W-]+$/;
// Trailing UTC designator or numeric offset (+hh, +hhmm, +hh:mm).
const OFFSET_SUFFIX = /(?:Z|([+-])(\d{2})(?::?(\d{2}))?)$/;

/**
 * Makes the offset explicit so that lib.parseISO never takes its
 * local-time branch (which depends on the host time zone).
 * Strings without an offset are treated as UTC by appending "Z".
 */
function toUtcInput(s: string): string {
  if (typeof s !== "string") {
    throw new RangeError(`Not a valid date: ${typeof s}`);
  }

  // Split at the first 'T' or space (the date/time delimiter).
  const m = /^([^T ]*)(?:[T ](.*))?$/.exec(s);
  if (!m) {
    throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(s)}`);
  }

  const datePart = m[1];
  const timePart = m[2];

  if (!DATE_PART.test(datePart)) {
    throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(s)}`);
  }

  // Date-only input: interpret as midnight UTC.
  if (timePart === undefined) {
    return `${datePart}T00:00Z`;
  }

  if (timePart === "") {
    throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(s)}`);
  }

  const off = OFFSET_SUFFIX.exec(timePart);
  if (off) {
    const body = timePart.slice(0, off.index);
    if (body === "") {
      throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(s)}`);
    }
    if (off[1] !== undefined) {
      const hours = Number(off[2]);
      const minutes = Number(off[3] ?? "0");
      if (hours > 23 || minutes > 59) {
        throw new RangeError(`Invalid UTC offset: ${JSON.stringify(s)}`);
      }
    }
    return s;
  }

  // No offset: the input is UTC.
  return `${s}Z`;
}

function parseEpoch(s: string): number {
  const input = toUtcInput(s);

  let date: Date;
  try {
    date = lib.parseISO(input);
  } catch {
    throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(s)}`);
  }

  const ms = date.getTime();
  if (Number.isNaN(ms)) {
    throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(s)}`);
  }
  return ms;
}

export function solve(stamps: string[]): number[] {
  if (!Array.isArray(stamps)) {
    throw new RangeError("Expected an array of date strings");
  }
  return stamps.map(parseEpoch).sort((a, b) => a - b);
}

const MS_PER_DAY = 86400000;
const MS_PER_HOUR = 3600000;
const MS_PER_MINUTE = 60000;
const MAX_EPOCH_MS = 8.64e15;

type ParsedDate = { days: number; ext: boolean | null };

function bad(): never {
  throw new RangeError("invalid");
}

function isLeapYear(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  if (m === 2) return isLeapYear(y) ? 29 : 28;
  return [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
}

function mod7(n: number): number {
  return ((n % 7) + 7) % 7;
}

// Days since 1970-01-01 for a proleptic Gregorian date (m: 1..12, d: 1..31).
function daysFromCivil(y: number, m: number, d: number): number {
  const yy = m <= 2 ? y - 1 : y;
  const era = Math.floor(yy / 400);
  const yoe = yy - era * 400;
  const mp = (m + 9) % 12; // March = 0
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

// ISO weekday (Mon=1..Sun=7) of an epoch day; 1970-01-01 was a Thursday.
function isoWeekdayOfDay(n: number): number {
  return mod7(n + 3) + 1;
}

function isoWeeksInYear(y: number): number {
  const p = (v: number): number =>
    mod7(v + Math.floor(v / 4) - Math.floor(v / 100) + Math.floor(v / 400));
  return p(y) === 4 || p(y - 1) === 3 ? 53 : 52;
}

function parseYear(t: string): number {
  if (t.length === 7) {
    // expanded representation: sign + 6 digits; "-000000" is not allowed
    const v = Number(t.slice(1));
    if (t[0] === "-" && v === 0) bad();
    return t[0] === "-" ? -v : v;
  }
  return Number(t);
}

function parseDate(s: string): ParsedDate {
  let m: RegExpMatchArray | null;

  // Calendar, extended: YYYY, YYYY-MM, YYYY-MM-DD (also expanded years)
  m = s.match(/^([+-]\d{6}|\d{4})(?:(-)(\d{2})(?:-(\d{2}))?)?$/);
  if (m) {
    const y = parseYear(m[1]);
    const mo = m[3] === undefined ? 1 : Number(m[3]);
    const d = m[4] === undefined ? 1 : Number(m[4]);
    if (mo < 1 || mo > 12) bad();
    if (d < 1 || d > daysInMonth(y, mo)) bad();
    const ext = m[2] !== undefined || m[1].length === 7 ? true : null;
    return { days: daysFromCivil(y, mo, d), ext };
  }

  // Calendar, basic: YYYYMMDD
  m = s.match(/^(\d{4})(\d{2})(\d{2})$/);
  if (m) {
    const y = Number(m[1]);
    const mo = Number(m[2]);
    const d = Number(m[3]);
    if (mo < 1 || mo > 12) bad();
    if (d < 1 || d > daysInMonth(y, mo)) bad();
    return { days: daysFromCivil(y, mo, d), ext: false };
  }

  // Week, extended: YYYY-Www, YYYY-Www-D
  m = s.match(/^([+-]\d{6}|\d{4})-W(\d{2})(?:-(\d))?$/);
  if (m) {
    return { days: weekDate(parseYear(m[1]), Number(m[2]), m[3] === undefined ? 1 : Number(m[3])), ext: true };
  }

  // Week, basic: YYYYWww, YYYYWwwD
  m = s.match(/^(\d{4})W(\d{2})(\d)?$/);
  if (m) {
    return { days: weekDate(Number(m[1]), Number(m[2]), m[3] === undefined ? 1 : Number(m[3])), ext: false };
  }

  // Ordinal, extended: YYYY-DDD
  m = s.match(/^([+-]\d{6}|\d{4})-(\d{3})$/);
  if (m) {
    const y = parseYear(m[1]);
    return { days: ordinalDate(y, Number(m[2])), ext: true };
  }

  // Ordinal, basic: YYYYDDD
  m = s.match(/^(\d{4})(\d{3})$/);
  if (m) {
    return { days: ordinalDate(Number(m[1]), Number(m[2])), ext: false };
  }

  return bad();
}

function weekDate(y: number, week: number, wd: number): number {
  if (wd < 1 || wd > 7) bad();
  if (week < 1 || week > isoWeeksInYear(y)) bad();
  const jan4 = daysFromCivil(y, 1, 4);
  const monday1 = jan4 - (isoWeekdayOfDay(jan4) - 1);
  return monday1 + (week - 1) * 7 + (wd - 1);
}

function ordinalDate(y: number, doy: number): number {
  const len = isLeapYear(y) ? 366 : 365;
  if (doy < 1 || doy > len) bad();
  return daysFromCivil(y, 1, 1) + doy - 1;
}

// Milliseconds contributed by a decimal fraction of a unit (truncated).
function fractionMs(unit: number, digits: string): number {
  if (digits.length === 0) return 0;
  const n = Math.min(digits.length, 9);
  const v = Number(digits.slice(0, n));
  return Math.floor((unit * v) / Math.pow(10, n));
}

const RE_TIME =
  /^(\d{2})(?:(:?)(\d{2})(?:\2(\d{2}))?)?(?:[.,](\d+))?(Z|z|[+-]\d{2}(?::?\d{2})?)?$/;
const RE_OFFSET = /^([+-])(\d{2})(?:(:?)(\d{2}))?$/;

function parseStampUnsafe(input: string): number {
  if (typeof input !== "string") bad();

  const tIdx = input.search(/[Tt]/);
  const datePart = tIdx < 0 ? input : input.slice(0, tIdx);
  const timePart = tIdx < 0 ? null : input.slice(tIdx + 1);

  const dp = parseDate(datePart);

  let total: number;

  if (timePart === null) {
    total = dp.days * MS_PER_DAY;
  } else {
    const tm = timePart.match(RE_TIME);
    if (!tm) bad();

    const hh = Number(tm[1]);
    const hasMin = tm[3] !== undefined;
    const hasSec = tm[4] !== undefined;
    const mm = hasMin ? Number(tm[3]) : 0;
    const ss = hasSec ? Number(tm[4]) : 0;
    const frac = tm[5] === undefined ? "" : tm[5];
    const offStr = tm[6];

    // Basic vs extended format must be used consistently.
    const known: boolean | null =
      dp.ext !== null ? dp.ext : hasMin ? tm[2] === ":" : null;
    if (hasMin && known !== null && (tm[2] === ":") !== known) bad();

    if (hh > 24 || mm > 59 || ss > 60) bad();
    if (hh === 24 && (mm !== 0 || ss !== 0 || /[1-9]/.test(frac))) bad();
    // Leap second only at 23:59:60 (local time).
    if (ss === 60 && !(hh === 23 && mm === 59)) bad();

    let fracMs = 0;
    if (frac.length > 0) {
      if (hasSec) fracMs = fractionMs(1000, frac);
      else if (hasMin) fracMs = fractionMs(MS_PER_MINUTE, frac);
      else fracMs = fractionMs(MS_PER_HOUR, frac);
    }

    let offMs = 0;
    if (offStr !== undefined && offStr !== "Z" && offStr !== "z") {
      const om = offStr.match(RE_OFFSET);
      if (!om) bad();
      const sign = om[1] === "-" ? -1 : 1;
      const oh = Number(om[2]);
      const omin = om[4] === undefined ? 0 : Number(om[4]);
      if (oh > 23 || omin > 59) bad();
      if (om[4] !== undefined && known !== null && (om[3] === ":") !== known) bad();
      offMs = sign * (oh * MS_PER_HOUR + omin * MS_PER_MINUTE);
    }

    total =
      dp.days * MS_PER_DAY +
      hh * MS_PER_HOUR +
      mm * MS_PER_MINUTE +
      ss * 1000 +
      fracMs -
      offMs;
  }

  if (!Number.isFinite(total) || Math.abs(total) > MAX_EPOCH_MS) bad();
  return total;
}

function parseStamp(input: string): number {
  try {
    return parseStampUnsafe(input);
  } catch (e) {
    throw new RangeError(`Invalid ISO 8601 date/date-time: ${String(input)}`);
  }
}

export function solve(stamps: string[]): number[] {
  if (!Array.isArray(stamps)) {
    throw new RangeError("Expected an array of ISO 8601 strings");
  }
  const result: number[] = [];
  for (let i = 0; i < stamps.length; i++) {
    result.push(parseStamp(stamps[i]));
  }
  result.sort((a, b) => a - b);
  return result;
}
